INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nobunaga-no-yabou-jeurasia', 'GAMEBOYADVANCE', 'Nobunaga no Yabou (J)(Eurasia)', '2001', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Grand strategy and management simulation of the Sengoku period.', 'Unify the provinces of Japan under your clan''s rule.', 'Legendary grand strategy simulation.', 'Nobunaga''s Ambition (Nobunaga no Yabou) on GBA brings the classic Koei strategy series to the handheld. Manage your fiefdom, engage in diplomacy, and lead your troops to victory in this complex and immersive historical sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('noddy---a-day-in-toyland-esir-vg', 'GAMEBOYADVANCE', 'Noddy - A Day In Toyland (E)(Sir VG)', '2001', 'Adventure', 'Creatures', '1', 'Children Adventure', 'Mini-game collection and exploration based on the children''s show.', 'Help Noddy complete his errands around Toyland.', 'Friendly educational adventure for children.', 'Noddy: A Day in Toyland is a charming GBA game designed for younger players. Explore Toyland, interact with Big Ears and Bumpy Dog, and solve simple puzzles in a colorful and safe environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('noddy---a-day-in-toyland-urising-sun', 'GAMEBOYADVANCE', 'Noddy - A day in Toyland (U)(Rising Sun)', '2001', 'Adventure', 'Creatures', '1', 'Children Adventure', 'Mini-game collection and exploration based on the children''s show.', 'Help Noddy complete his errands around Toyland.', 'Friendly educational adventure for children.', 'Noddy: A Day in Toyland is a charming GBA game designed for younger players. Explore Toyland, interact with Big Ears and Bumpy Dog, and solve simple puzzles in a colorful and safe environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nonono-puzzle-chailien-jrivalroms', 'GAMEBOYADVANCE', 'Nonono Puzzle Chailien (J)(RivalRoms)', '2002', 'Puzzle', 'Success', '1', 'Puzzle', 'Physics-based puzzle game where you rotate the world to move objects.', 'Guide the Chailien creatures to the goal by tilting the stage.', 'Innovative gravity-based puzzle game.', 'Nonono Puzzle Chailien is a unique puzzle title from Nintendo. Use the GBA''s buttons to rotate the environment and guide the characters. It’s a clever, colorful, and highly addictive puzzle game that showcases Nintendo’s creativity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nos-voisins-les-hommes-findependent', 'GAMEBOYADVANCE', 'Nos Voisins les Hommes (F)(Independent)', '2006', 'Action', 'Independent Arts', '1', 'Action Adventure', '2D platformer with character-switching and heist mechanics.', 'Complete various missions to gather food and outsmart the humans.', 'Heist-themed platforming based on the movie.', 'Over the Hedge (Nos Voisins les Hommes) on GBA lets you play as RJ and Verne. Navigate human backyards, dodge traps, and collect items in this fun action-platformer that follows the plot of the animated film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nyan-nyan-nyanko-no-nyan-collection-jcaravan', 'GAMEBOYADVANCE', 'Nyan Nyan Nyanko no Nyan Collection (J)(Caravan)', '2000', 'Compilation', 'Jaleco', '1', 'Minigame Collection', 'Virtual pet and collection game featuring cute "Nyanko" cats.', 'Collect all the different Nyanko cats and care for them.', 'Cute cat-themed collection and care sim.', 'Nyan Nyan Nyanko no Nyan Collection is a delightful Japanese sim. Based on the popular San-X characters, it focuses on collecting cats that look like various food items. A relaxing and adorable game for cat lovers and collectors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochainu-kururin-jcaravan', 'GAMEBOYADVANCE', 'Ochainu Kururin (J)(Caravan)', '2001', 'Puzzle', 'Eighting', '1', 'Physics Puzzle', 'Rotating bar navigation through narrow, obstacle-filled courses.', 'Reach the end of the maze without hitting the walls.', 'Precise and addictive puzzle-action game.', 'Ochainu Kururin brings the classic Kururin mechanics to the GBA with a cute tea-dog theme. Master the art of rotating through tight spaces in this challenging puzzle game that tests your timing and spatial awareness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochainu-no-bouken-jima-jsupplex', 'GAMEBOYADVANCE', 'Ochainu no Bouken Jima (J)(sUppLeX)', '2002', 'Adventure', 'AlphaDream', '1', 'Children Adventure', '2D platforming and exploration on a themed island.', 'Explore the island and collect items while avoiding obstacles.', 'Charming platforming adventure with tea-dogs.', 'Ochainu no Bouken Jima takes the Ochainu characters on an island adventure. Featuring bright colors and accessible platforming, it’s a perfect title for fans of the Japanese franchise looking for portable fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochaken-no-heya-jrising-sun', 'GAMEBOYADVANCE', 'Ochaken No Heya (J)(Rising Sun)', '2002', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Life simulation and room decoration with virtual pets.', 'Interact with tea-dogs and customize their living space.', 'Relaxing virtual pet and room management sim.', 'Ochaken No Heya is a peaceful simulation where you care for the popular Japanese tea-dogs. Decorate rooms, play mini-games, and collect items in this charming and relaxing handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochaken-no-yumebouken-jcaravan', 'GAMEBOYADVANCE', 'Ochaken no Yumebouken (J)(Caravan)', '2003', 'Adventure', 'MTO', '1', 'Children Adventure', 'Side-scrolling adventure with puzzle elements and mini-games.', 'Journey through dream-like worlds to solve puzzles.', 'Dream-themed adventure starring Ochaken characters.', 'Ochaken no Yumebouken offers a variety of gameplay styles set in a whimsical dream world. Help the tea-dogs navigate levels and complete tasks in this colorful and family-friendly GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oddworld---munchs-oddysee-grising-sun', 'GAMEBOYADVANCE', 'Oddworld - Munch''s Oddysee (G)(Rising Sun)', '2003', 'Action', 'Oddworld Inhabitants', '1', 'Action Platformer', 'Isometric 2D action-adventure with platforming and puzzles.', 'Help Munch and Abe escape the Vykkers and save their kind.', 'Portable entry in the quirky Oddworld saga.', 'Oddworld: Munch''s Oddysee on GBA translates the unique atmosphere of the series into an isometric adventure. Use psychic powers and teamwork to solve puzzles and escape captivity in this cult-classic sci-fi story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oddworld---munchs-oddysee-urising-sun', 'GAMEBOYADVANCE', 'Oddworld - Munch''s Oddysee (U)(Rising Sun)', '2003', 'Action', 'Oddworld Inhabitants', '1', 'Action Platformer', 'Isometric 2D action-adventure with platforming and puzzles.', 'Help Munch and Abe escape the Vykkers and save their kind.', 'Portable entry in the quirky Oddworld saga.', 'Oddworld: Munch''s Oddysee on GBA translates the unique atmosphere of the series into an isometric adventure. Use psychic powers and teamwork to solve puzzles and escape captivity in this cult-classic sci-fi story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ohanaya-san-monogatari-jgbanow', 'GAMEBOYADVANCE', 'Ohanaya-san Monogatari (J)(GBANow)', '2003', 'Simulation', 'MTO', '1', 'Shop Simulation', 'Shop management simulation focused on running a flower shop.', 'Grow flowers, fulfill customer orders, and manage the business.', 'Florist management and business simulation.', 'Ohanaya-san Monogatari lets you live the life of a professional florist. Learn to care for different plants and build a successful business in this detailed and relaxing Japanese career simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ohanaya-san-ni-narou!-jkamx', 'GAMEBOYADVANCE', 'Ohanaya-san ni narou! (J)(kaMX)', '2002', 'Simulation', 'MTO', '1', 'Shop Simulation', 'Career simulation focused on floral arrangements and sales.', 'Become the best florist by creating beautiful arrangements.', 'Charming flower shop career simulation.', 'Ohanaya-san ni narou! is a career-focused game where you manage a flower boutique. Interact with customers and master floral design in this engaging life simulation for the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ojaru-maru---tsuki-hikari-machi-tour-de-ojaru-jtrashman', 'GAMEBOYADVANCE', 'Ojaru Maru - Tsuki Hikari Machi Tour de Ojaru (J)(Trashman)', '2000', 'Adventure', 'TOSE', '1', 'Anime Adventure', 'Minigame-based adventure featuring the Ojaru Maru characters.', 'Explore the town and complete various character interactions.', 'Whimsical adventure based on the popular anime.', 'Ojaru Maru: Tsuki Hikari Machi Tour takes you to the world of the hit Japanese anime. Engage in light-hearted mini-games and follow a charming narrative in this portable tour of Ojaru Maru''s world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('okaitoku-series-5---puzzle-&-tantei-collection-jpatience', 'GAMEBOYADVANCE', 'Okaitoku Series 5 - Puzzle & Tantei Collection (J)(Patience)', '2003', 'Puzzle', 'Success', '1', 'Puzzle Collection', 'Collection of classic puzzles and detective-style mysteries.', 'Solve various logic puzzles and criminal cases.', 'Puzzle and detective mini-game compilation.', 'Okaitoku Series 5 provides hours of brain-teasing fun. From classic logic puzzles to detective work, it’s a perfect title for players who enjoy testing their wits on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('okuman-chouja-game-jindependent', 'GAMEBOYADVANCE', 'Okuman Chouja Game (J)(Independent)', '2001', 'Board Game', 'Taito', '1', 'Board Game', 'Board game simulation based on accumulating wealth and property.', 'Become a billionaire by making smart investments and winning.', 'Traditional Japanese "Millionaire" board game.', 'Okuman Chouja Game is a digital board game where the goal is financial dominance. Compete against AI or friends to buy properties and manage assets in this strategic Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece---going-baseball-haejeok-yaku-kindependent', 'GAMEBOYADVANCE', 'One Piece - Going Baseball Haejeok Yaku (K)(Independent)', '2004', 'Sports', 'Dimps', '4', 'Arcade Baseball', 'Baseball simulation featuring characters from the One Piece anime.', 'Win baseball matches using special "Devil Fruit" abilities.', 'Wacky anime-themed arcade baseball action.', 'One Piece Going Baseball brings Luffy and the Straw Hat crew to the diamond. Use super-powered hits and pitches to win tournaments in this unique sports spin-off of the legendary series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece---mezase!-king-of-paris-jcezar', 'GAMEBOYADVANCE', 'One Piece - Mezase! King of Paris (J)(Cezar)', '2004', 'Adventure', 'Ganbarion', '1', 'Action Adventure', 'Competitive board game with mini-games and exploration.', 'Race through Paris-themed levels to reach the goal first.', 'One Piece themed board game adventure.', 'One Piece: Mezase! King of Paris combines strategic board movement with fun mini-games. Play as your favorite pirates and navigate the map to win in this Japan-exclusive GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece---nanatsu-shima-no-daihihou-jcezar', 'GAMEBOYADVANCE', 'One Piece - Nanatsu Shima no Daihihou (J)(Cezar)', '2002', 'Adventure', 'Ganbarion', '1', 'Action Adventure', 'Action-adventure with exploration and combat on seven islands.', 'Find the legendary treasure hidden across the mysterious islands.', 'Grand One Piece adventure with exploration and battles.', 'One Piece: Nanatsu Shima no Daihihou is a deep action game where you control the Straw Hat crew. Explore vast environments, fight enemies, and uncover secrets in this epic pirate journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece-dragon-dream-jcaravan', 'GAMEBOYADVANCE', 'One Piece Dragon Dream (J)(Caravan)', '2005', 'Adventure', 'Ganbarion', '1', 'Action Adventure', 'Turn-based RPG with an original storyline and dream world theme.', 'Navigate through dreams to recover lost memories and items.', 'Story-driven RPG set in the One Piece universe.', 'One Piece Dragon Dream offers a unique turn-based battle system and a deep narrative. Explore the world of dreams and face off against iconic villains in this polished Japanese JRPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece-going-baseball-jeurasia', 'GAMEBOYADVANCE', 'One Piece Going Baseball (J)(Eurasia)', '2002', 'Sports', 'Now Production', '4', 'Arcade Baseball', 'Baseball simulation featuring characters from the One Piece anime.', 'Win baseball matches using special "Devil Fruit" abilities.', 'Wacky anime-themed arcade baseball action.', 'One Piece Going Baseball brings Luffy and the Straw Hat crew to the diamond. Use super-powered hits and pitches to win tournaments in this unique sports spin-off of the legendary series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('onimusha-tactics-epatience', 'GAMEBOYADVANCE', 'Onimusha Tactics (E)(Patience)', '2003', 'Strategy', 'Capcom', '1', 'Tactical RPG', 'Grid-based tactical RPG with unit management and upgrades.', 'Defeat the Genma army by strategically placing your warriors.', 'High-quality tactical RPG in the Onimusha universe.', 'Onimusha Tactics is a deep strategy game featuring turn-based combat on isometric grids. Build your team, upgrade weapons with souls, and stop the demon invasion in this acclaimed GBA tactical title.');
