INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('onmyou-taisenki-zeroshiki-jcaravan', 'GAMEBOYADVANCE', 'Onmyou Taisenki Zeroshiki (J)(Caravan)', '2004', 'Action', 'Konami', '1', 'Action Strategy', 'Card-based battle RPG with character collection and leveling.', 'Win card duels to become the ultimate Onmyou Master.', 'Strategic card-battling RPG based on the series.', 'Onmyou Taisenki Zeroshiki focuses on strategic card duels. Collect powerful spirits, build a winning deck, and progress through the story in this engaging Japanese RPG experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('open-season-erising-sun', 'GAMEBOYADVANCE', 'Open Season (E)(Rising Sun)', '2006', 'Adventure', 'Artificial Mind and Movement', '1', 'Action Adventure', '2D action-adventure with platforming and puzzle-solving.', 'Help Boog and Elliot find their way back home.', 'Fun animal adventure based on the animated movie.', 'Open Season on GBA follows the plot of the film with engaging platforming levels. Use Boog’s strength and Elliot’s speed to overcome obstacles and return to the forest in this colorful adventure.');
