INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation-armored-liberty-urising-sun', 'GAMEBOYADVANCE', 'Operation Armored Liberty (U)(Rising Sun)', '2003', 'Shooter', 'Mastiff', '1', 'Run and Gun', 'Side-scrolling run-and-gun action with vehicle segments.', 'Defeat enemy forces and complete military missions.', 'Intense military-themed action shooter.', 'Operation Armored Liberty delivers fast-paced shooting action. Navigate through warzones, use different weapons, and pilot vehicles to take down the opposition in this classic handheld military shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oriental-blue---ao-no-tengai-jcezar', 'GAMEBOYADVANCE', 'Oriental Blue - Ao no Tengai (J)(Cezar)', '2003', 'RPG', 'Hudson Soft', '1', 'Japanese RPG', 'Open-world turn-based JRPG with a deep story and magic system.', 'Journey through a fantasy world to stop an ancient threat.', 'Masterpiece RPG with beautiful art and deep mechanics.', 'Oriental Blue: Ao no Tengai is a spiritual successor to the Tengai Makyou series. Featuring a non-linear story and a unique magic fusion system, it is one of the most respected JRPGs on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('original-sunset-wilds-title-card-&-sprites-for-mk---sc-by-scd', 'GAMEBOYADVANCE', 'Original Sunset Wilds title card & sprites for MK - SC by SCD', '2003', 'Racing', 'Nintendo', '1', 'Racing (Hack)', 'Modification or showcase of game assets and title screens.', 'View or implement custom sprites and title cards.', 'Asset collection for Mario Kart: Super Circuit modding.', 'This entry represents a custom project featuring the Sunset Wilds track. It showcases the creative modding community for GBA, providing high-quality assets and title cards for enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshaberi-inco-club-jchakky', 'GAMEBOYADVANCE', 'Oshaberi Inco Club (J)(Chakky)', '2002', 'Simulation', 'MTO', '1', 'Voice Interaction', 'Virtual pet simulation focused on teaching an parrot to talk.', 'Care for your parrot and train it to repeat words and phrases.', 'Unique talking parrot simulation and care.', 'Oshaberi Inco Club lets you raise a digital parrot. Use the in-game mechanics to teach your bird to talk, feed it, and keep it happy in this charming Japanese pet sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshare-princess-jchakky', 'GAMEBOYADVANCE', 'Oshare Princess (J)(Chakky)', '2003', 'Simulation', 'MTO', '1', 'Fashion Simulation', 'Fashion and lifestyle simulation focused on dressing up characters.', 'Become a fashion icon by creating the best outfits and styles.', 'Cute fashion-focused dress-up simulation.', 'Oshare Princess is a dream for fashion lovers. Choose from hundreds of clothing items, style your hair, and participate in fashion shows in this creative and colorful Japanese GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshare-princess-2-and-doubutsu-kyaranabi-jmugs', 'GAMEBOYADVANCE', 'Oshare Princess 2 And Doubutsu Kyaranabi (J)(Mugs)', '2004', 'Simulation', 'MTO', '1', 'Fashion Simulation', 'Enhanced fashion simulation with animal character interaction.', 'Master the fashion world while caring for animal companions.', 'Fashion and pet lifestyle simulation sequel.', 'This sequel adds a unique twist by combining fashion design with animal companions. Style your character and interact with cute animals in this expanded lifestyle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshare-princess-3-jrising-sun', 'GAMEBOYADVANCE', 'Oshare Princess 3 (J)(Rising Sun)', '2005', 'Simulation', 'MTO', '1', 'Fashion Simulation', 'Advanced fashion simulation with new clothing and competition modes.', 'Win fashion competitions and unlock the latest styles.', 'Deep fashion simulation with competitive elements.', 'Oshare Princess 3 offers even more customization options and challenges. Build your reputation as a stylist and dominate the fashion scene in this polished Japanese sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshare-princess-5-jsupplex', 'GAMEBOYADVANCE', 'Oshare Princess 5 (J)(Supplex)', '2005', 'Simulation', 'MTO', '1', 'Fashion Simulation', 'The fifth entry in the series with maximum customization options.', 'Reach the top of the fashion world with elite styling.', 'Definitive fashion and lifestyle GBA simulation.', 'Oshare Princess 5 is the peak of the series, featuring the most clothing items and refined gameplay. Create stunning looks and live the life of a fashionista in this popular Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshare-princess-ex-primo-debut-monogatari-&-renai-uranai-daisakusen-jcaravan', 'GAMEBOYADVANCE', 'Oshare Princess EX Primo Debut Monogatari & Renai Uranai Daisakusen (J)(Caravan)', '2004', 'Simulation', 'MTO', '1', 'Fashion Simulation', 'Fashion simulation combined with romance and fortune-telling.', 'Find the perfect outfit and discover your romantic future.', 'Fashion, romance, and fortune-telling hybrid.', 'This "EX" version blends classic dress-up gameplay with romantic subplots and fortune-telling mini-games, providing a unique variety of lifestyle content for GBA players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshare-wanko-jsupplex', 'GAMEBOYADVANCE', 'Oshare Wanko (J)(Supplex)', '2004', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation focused on caring for and styling puppies.', 'Raise and dress up adorable puppies to win contests.', 'Cute puppy care and fashion simulation.', 'Oshare Wanko combines pet care with the series'' signature fashion focus. Groom and dress your dogs in the cutest outfits to compete in puppy beauty contests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ottifanten-pinball-grising-sun', 'GAMEBOYADVANCE', 'Ottifanten Pinball (G)(Rising Sun)', '2002', 'Pinball', 'DSI Games', '1', 'Pinball', 'Arcade pinball physics with themed tables featuring the Ottifanten characters.', 'Score maximum points by hitting targets and completing table missions.', 'Fun and quirky cartoon-themed pinball action.', 'Ottifanten Pinball brings the popular German cartoon characters to the GBA. Featuring colorful tables, hidden bonuses, and classic arcade physics, it''s a delightful experience for pinball enthusiasts and fans of the franchise alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ougon-no-taiyo-jeurasia', 'GAMEBOYADVANCE', 'Ougon no Taiyo (J)(Eurasia)', '2001', 'RPG', 'Camelot Software Planning', '1', 'Japanese RPG', 'Turn-based JRPG with a deep "Djinn" magic system and environmental puzzles.', 'Prevent the release of Alchemy and save the world of Weyard.', 'Masterpiece fantasy RPG with stunning 2D visuals.', 'Golden Sun (Ougon no Taiyo) is one of the most acclaimed GBA JRPGs. Use Psynergy to solve puzzles and master the Djinn system in strategic battles. A deep narrative and beautiful graphics make this a must-play classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ougon-no-taiyou---shitsu-warate-jidai-jeurasia', 'GAMEBOYADVANCE', 'Ougon no Taiyou - Shitsu Warate Jidai (J)(Eurasia)', '2002', 'RPG', 'Camelot Software Planning', '1', 'Japanese RPG', 'Turn-based JRPG featuring a complex magic system and puzzle-solving.', 'Continue the epic journey to stop the lighting of the elemental beacons.', 'The epic sequel to the legendary Golden Sun series.', 'Ougon no Taiyou: Shitsu Warate Jidai (The Lost Age) expands on everything that made the first game great. Transfer your data and explore a vast world using Psynergy in this definitive handheld role-playing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('our-breeding-series---my-ameba-jeurasia', 'GAMEBOYADVANCE', 'Our Breeding Series - My Ameba (J)(Eurasia)', '2002', 'Simulation', 'Altron', '1', 'Microorganism Simulation', 'Virtual pet simulation focused on culturing and evolving microscopic life.', 'Raise and evolve your Ameba by managing its environment and food.', 'Unique microscopic creature-raising simulation.', 'Our Breeding Series: My Ameba offers a different take on the pet sim genre. Focus on the delicate balance of microscopic life, evolving your creature through various stages in this relaxing Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('our-breeding-series---my-beetle-jeurasia', 'GAMEBOYADVANCE', 'Our Breeding Series - My Beetle (J)(Eurasia)', '2002', 'Simulation', 'Altron', '1', 'Insect Breeding Simulation', 'Virtual pet simulation focused on collecting and breeding beetles.', 'Grow the strongest beetle to win in competitive insect battles.', 'Insect collection and breeding battle simulation.', 'Our Breeding Series: My Beetle lets you experience the popular Japanese hobby of beetle breeding. Care for your insect, manage its diet, and train it to become the champion of the beetle wrestling ring.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge---beesten-bij-de-buren-nindependent', 'GAMEBOYADVANCE', 'Over the Hedge - Beesten Bij de Buren (N)(Independent)', '2006', 'Action', 'Vicarious Visions', '1', 'Action Platformer', '2D platformer with stealth elements and character swapping mechanics.', 'Infiltrate human suburban homes to gather food and supplies.', 'Heist-themed platformer based on the animated film.', 'Over the Hedge (Beesten Bij de Buren) brings the movie''s charm to GBA. Play as RJ and Verne, navigate backyard traps, and use stealth to outsmart the humans in this engaging action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge---hammy-goes-nuts-erising-sun', 'GAMEBOYADVANCE', 'Over the Hedge - Hammy Goes Nuts (E)(Rising Sun)', '2006', 'Action', 'Vicarious Visions', '1', 'Action Platformer', 'Action-adventure focused on fast-paced puzzles and environmental interaction.', 'Help Hammy the squirrel find his lost nuts and navigate obstacles.', 'Fast-paced action spin-off starring Hammy.', 'Over the Hedge: Hammy Goes Nuts is a high-energy adventure for GBA. Control the hyperactive Hammy through tricky levels, using his speed to solve puzzles and overcome challenges in this fun movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge---hammy-goes-nuts-urising-sun', 'GAMEBOYADVANCE', 'Over the Hedge - Hammy Goes Nuts (U)(Rising Sun)', '2006', 'Action', 'Vicarious Visions', '1', 'Action Platformer', 'Action-adventure focused on fast-paced puzzles and environmental interaction.', 'Help Hammy the squirrel find his lost nuts and navigate obstacles.', 'Fast-paced action spin-off starring Hammy.', 'Over the Hedge: Hammy Goes Nuts is a high-energy adventure for GBA. Control the hyperactive Hammy through tricky levels, using his speed to solve puzzles and overcome challenges in this fun movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge-eindependent', 'GAMEBOYADVANCE', 'Over the Hedge (E)(Independent)', '2006', 'Action', 'Vicarious Visions', '1', 'Action Platformer', '2D platformer with stealth elements and character swapping mechanics.', 'Infiltrate human suburban homes to gather food and supplies.', 'Heist-themed platformer based on the animated film.', 'Over the Hedge brings the movie''s charm to GBA. Play as RJ and Verne, navigate backyard traps, and use stealth to outsmart the humans in this engaging action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge-utrashman', 'GAMEBOYADVANCE', 'Over the Hedge (U)(Trashman)', '2006', 'Action', 'Vicarious Visions', '1', 'Action Platformer', '2D platformer with stealth elements and character swapping mechanics.', 'Infiltrate human suburban homes to gather food and supplies.', 'Heist-themed platformer based on the animated film.', 'Over the Hedge brings the movie''s charm to GBA. Play as RJ and Verne, navigate backyard traps, and use stealth to outsmart the humans in this engaging action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ozzy-&-drix-uindependent', 'GAMEBOYADVANCE', 'Ozzy & Drix (U)(Independent)', '2005', 'Action', 'Griptonite Games', '1', 'Action Platformer', 'Side-scrolling action platformer set inside the human body.', 'Combat germs and viruses to keep the host healthy.', 'Action-packed platformer based on the TV show.', 'Ozzy & Drix brings the microscopic world of the animated series to GBA. Control the white blood cell and the cold pill through diverse levels, using unique abilities to fight off infections in this creative action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paard-&-pony---mijn-manege-esupplex', 'GAMEBOYADVANCE', 'Paard & Pony - Mijn Manege (E)(sUppLeX)', '2005', 'Simulation', 'Tivola', '1', 'Horse Simulation', 'Horse care and stable management simulation.', 'Manage a successful stable by training and caring for your horses.', 'Immersive horse riding and management sim.', 'Paard & Pony: Mijn Manege allows you to run your own horse stable. Focus on grooming, feeding, and training your horses for competitions in this detailed and educational simulation for animal lovers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paard-&-pony---paard-in-galop-esupplex', 'GAMEBOYADVANCE', 'Paard & Pony - Paard in Galop (E)(sUppLeX)', '2005', 'Simulation', 'Tivola', '1', 'Horse Racing Simulation', 'Equestrian sports simulation focusing on horse riding and racing.', 'Compete in various riding events and win the championship.', 'Competitive horse riding and racing simulation.', 'Paard & Pony: Paard in Galop focuses on the thrill of the race. Master horse handling and compete in various equestrian disciplines to become the ultimate rider in this charming GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-collection-elightforce', 'GAMEBOYADVANCE', 'Pac-Man Collection (E)(Lightforce)', '2001', 'Arcade', 'Namco', '1', 'Arcade Compilation', 'Arcade collection featuring Pac-Man, Pac-Attack, and Pac-Man Arrangement.', 'Reach high scores in various classic and updated Pac-Man titles.', 'Essential collection of Pac-Man arcade hits.', 'Pac-Man Collection brings four legendary games to one cartridge. Whether you enjoy the original arcade classic or the puzzle-focused Pac-Attack, this is the definitive way to play Pac-Man on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-collection-jcezar', 'GAMEBOYADVANCE', 'Pac-Man Collection (J)(Cezar)', '2001', 'Arcade', 'Namco', '1', 'Arcade Compilation', 'Arcade collection featuring Pac-Man, Pac-Attack, and Pac-Man Arrangement.', 'Reach high scores in various classic and updated Pac-Man titles.', 'Essential collection of Pac-Man arcade hits.', 'Pac-Man Collection brings four legendary games to one cartridge. Whether you enjoy the original arcade classic or the puzzle-focused Pac-Attack, this is the definitive way to play Pac-Man on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-collection-umode7', 'GAMEBOYADVANCE', 'Pac-Man Collection (U)(Mode7)', '2001', 'Arcade', 'Namco', '1', 'Arcade Compilation', 'Arcade collection featuring Pac-Man, Pac-Attack, and Pac-Man Arrangement.', 'Reach high scores in various classic and updated Pac-Man titles.', 'Essential collection of Pac-Man arcade hits.', 'Pac-Man Collection brings four legendary games to one cartridge. Whether you enjoy the original arcade classic or the puzzle-focused Pac-Attack, this is the definitive way to play Pac-Man on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-collection+', 'GAMEBOYADVANCE', 'Pac-Man Collection+', '2001', 'Arcade', 'Namco', '1', 'Arcade Compilation', 'Hybrid collection featuring arcade classics and a pinball simulation.', 'Master both arcade mazes and themed pinball tables.', 'Double pack featuring Pac-Man classics and Pinball.', 'This bundle offers the best of both worlds: the strategy of the Pac-Man Collection and the physics-based fun of Pac-Man Pinball Advance. Experience multiple ways to play with the world''s most famous yellow mascot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-pinball-advance-erising-sun', 'GAMEBOYADVANCE', 'Pac-Man Pinball Advance (E)(Rising Sun)', '2004', 'Pinball', 'Magic Pockets', '1', 'Pinball', 'Pinball simulation with Pac-Man themed tables and ghost mechanics.', 'Score points and clear objectives across various maze-like tables.', 'Addictive pinball action with a Pac-Man twist.', 'Pac-Man Pinball Advance combines classic pinball physics with iconic elements from the maze games. Battle ghosts and collect pellets on dynamic tables in this high-energy arcade experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-pinball-advance-utrashman', 'GAMEBOYADVANCE', 'Pac-Man Pinball Advance (U)(TrashMan)', '2004', 'Pinball', 'Magic Pockets', '1', 'Pinball', '2D side-scrolling platformer with puzzle and combat elements.', 'Rescue Pac-Man’s friends from the Ghost Island.', 'Classic platforming adventure with Pac-Man.', 'Pac-Man World brings the 3D console adventure to a 2D GBA perspective. Use the Rev-Roll and Butt-Bounce to defeat enemies and navigate through diverse worlds in this polished handheld platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-world-erising-sun', 'GAMEBOYADVANCE', 'Pac-Man World (E)(Rising Sun)', '2004', 'Platform', 'Namco', '1', '3D Platformer', '2D side-scrolling platformer with puzzle and combat elements.', 'Rescue Pac-Man’s friends from the Ghost Island.', 'Classic platforming adventure with Pac-Man.', 'Pac-Man World brings the 3D console adventure to a 2D GBA perspective. Use the Rev-Roll and Butt-Bounce to defeat enemies and navigate through diverse worlds in this polished handheld platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-world-uvenom', 'GAMEBOYADVANCE', 'Pac-Man World (U)(Venom)', '2004', 'Platform', 'Namco', '1', '3D Platformer', '2D platforming with enhanced graphics and new power-ups.', 'Defeat the ghost pirate Spooky to save Pac-Land.', 'Action-packed platforming sequel with Pac-Man.', 'Pac-Man World 2 on GBA offers faster gameplay and more complex levels than its predecessor. Navigate through forests, ice lands, and underwater stages to stop Spooky’s evil plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-world-2-etrashman', 'GAMEBOYADVANCE', 'Pac-Man World 2 (E)(Trashman)', '2005', 'Platform', 'Namco', '1', '3D Platformer', '2D platforming with enhanced graphics and new power-ups.', 'Defeat the ghost pirate Spooky to save Pac-Land.', 'Action-packed platforming sequel with Pac-Man.', 'Pac-Man World 2 on GBA offers faster gameplay and more complex levels than its predecessor. Navigate through forests, ice lands, and underwater stages to stop Spooky’s evil plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-world-2-utrashman', 'GAMEBOYADVANCE', 'Pac-Man World 2 (U)(Trashman)', '2005', 'Platform', 'Namco', '1', '3D Platformer', 'Retro arcade collection featuring Paperboy and Rampage.', 'Deliver newspapers safely and destroy cities as giant monsters.', 'Two legendary Midway arcade hits in one.', 'This double pack brings Paperboy''s neighborhood chaos and Rampage''s city-crushing action to the GBA. Perfect for fans of classic 80s arcade gameplay looking for a portable retro fix.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-&-rampage-esupplex', 'GAMEBOYADVANCE', 'Paperboy & Rampage (E)(Supplex)', '2001', 'Arcade', 'Midway', '2', 'Arcade Compilation', 'Retro arcade collection featuring Paperboy and Rampage.', 'Deliver newspapers safely and destroy cities as giant monsters.', 'Two legendary Midway arcade hits in one.', 'This double pack brings Paperboy''s neighborhood chaos and Rampage''s city-crushing action to the GBA. Perfect for fans of classic 80s arcade gameplay looking for a portable retro fix.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-&-rampage-utrashman', 'GAMEBOYADVANCE', 'Paperboy & Rampage (U)(Trashman)', '2001', 'Arcade', 'Midway', '2', 'Arcade Compilation', 'Side-scrolling adventure with puzzle-solving and quirky mini-games.', 'Help Patrick complete his wacky goals and explore Bikini Bottom.', 'Humorous underwater adventure starring Patrick Star.', 'Patrick Star on GBA is a fun and lighthearted adventure. Explore iconic locations from the show, solve puzzles, and engage in funny interactions in this accessible title perfect for SpongeBob SquarePants fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('patrick-star', 'GAMEBOYADVANCE', 'Patrick Star', '2004', 'Action', 'Fan Made', '1', 'Crossover Hack', 'Baseball simulation combined with RPG-style career development.', 'Build a successful baseball career through training and matches.', 'Strategic baseball and life simulation hybrid.', 'Pawa Poke Dash is part of the famous Power Pro series. It blends deep baseball mechanics with a story-driven career mode, making it a unique and addictive sports title for the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pawa-poke-dash-jcaravan', 'GAMEBOYADVANCE', 'Pawa Poke Dash (J)(Caravan)', '2004', 'Sports', 'Power Pro Productions', '1', 'Arcade Baseball', 'Business management and virtual pet care simulation.', 'Run a luxury resort for pets by meeting all their needs.', 'Pet hotel management and animal care sim.', 'Paws & Claws: Pet Resort puts you in charge of a high-end animal hotel. Groom, feed, and pamper various pets to grow your business and become the top resort manager in the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paws-&-claws---pet-resort-utrashman', 'GAMEBOYADVANCE', 'Paws & Claws - Pet Resort (U)(Trashman)', '2006', 'Simulation', 'Frontline Studios', '1', 'Pet Simulation', 'Top-down open-world action-driving game similar to early GTA.', 'Complete missions for criminal syndicates and earn money.', 'Intense open-world driving and action game.', 'Payback is often called the GTA of the GBA. Featuring a 3D-perspective city, various vehicles, and high-stakes missions, it’s one of the most ambitious and adult-oriented action games on the platform.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('payback-erising-sun', 'GAMEBOYADVANCE', 'Payback (E)(Rising Sun)', '2004', 'Action', 'Apex Designs', '1', 'Isometric Shooter', 'Tile-matching puzzle game with a unique aquatic theme.', 'Clear blocks and solve puzzles featuring the Uminin characters.', 'Charming and colorful Japanese puzzle game.', 'Pazunin: Uminin No Puzzle de Nimu is a delightful brain-teaser. Match colorful aquatic creatures and clear stages in this addictive and visually unique Japanese GBA puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pazunin---uminin-no-puzzle-de-nimu-jrising-sun', 'GAMEBOYADVANCE', 'Pazunin - Uminin No Puzzle de Nimu (J)(Rising Sun)', '2003', 'Puzzle', 'Skip Ltd.', '1', 'Puzzle Adventure', 'Customizable miniature car racing with arcade physics.', 'Win races and collect parts to upgrade your tiny car.', 'Fun and competitive miniature car racing.', 'Penny Racers (Choro Q) brings customizable micro-car racing to GBA. Tune your car''s engine, tires, and body to win across diverse tracks in this charming and strategic racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penny-racers-eevasion', 'GAMEBOYADVANCE', 'Penny Racers (E)(Evasion)', '2001', 'Racing', 'Genki', '4', 'Arcade Racing', 'Productivity application simulating a digital organizer.', 'Manage schedules, notes, and contacts on your GBA.', 'Digital organizer tool for the Game Boy Advance.', 'This application turns your GBA into a Personal Data Assistant. Manage your daily life with built-in tools for scheduling and notes, showcasing the non-gaming versatility of the handheld hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('personal-data-assistant-for-gameboy-advance-uindependent', 'GAMEBOYADVANCE', 'Personal Data Assistant for Gameboy Advance (U)(Independent)', '2002', 'Utility', 'Independent', '1', 'Personal Organizer', 'Productivity application simulating a digital organizer.', 'Manage schedules, notes, and contacts on your GBA.', 'Digital organizer tool for the Game Boy Advance.', 'This application turns your GBA into a Personal Data Assistant. Manage your daily life with built-in tools for scheduling and notes, showcasing the non-gaming versatility of the handheld hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peter-pan---return-to-neverland-elightforce', 'GAMEBOYADVANCE', 'Peter Pan - Return to Neverland (E)(Lightforce)', '2002', 'Action', 'Griptonite Games', '1', 'Action Platformer', 'Side-scrolling platforming with flight mechanics and combat.', 'Defeat Captain Hook and find the hidden treasure of Neverland.', 'Classic Disney platforming adventure in Neverland.', 'Peter Pan: Return to Neverland for GBA lets you fly and fight through beautiful levels. Master Peter''s movement, collect hidden items, and face off against pirates in this charming Disney movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peter-pan---return-to-neverland-uvenom', 'GAMEBOYADVANCE', 'Peter Pan - Return to Neverland (U)(Venom)', '2002', 'Action', 'Griptonite Games', '1', 'Action Platformer', 'Side-scrolling platforming with flight mechanics and combat.', 'Defeat Captain Hook and find the hidden treasure of Neverland.', 'Classic Disney platforming adventure in Neverland.', 'Peter Pan: Return to Neverland for GBA lets you fly and fight through beautiful levels. Master Peter''s movement, collect hidden items, and face off against pirates in this charming Disney movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peter-pan---the-motion-picture-erising-sun', 'GAMEBOYADVANCE', 'Peter Pan - The Motion Picture (E)(Rising Sun)', '2002', 'Action', 'Griptonite Games', '1', 'Action Platformer', 'Action-adventure with exploration and cinematic storytelling.', 'Follow the movie''s plot to save Neverland from the pirates.', 'Movie-based action adventure featuring Peter Pan.', 'Peter Pan: The Motion Picture brings the live-action magic to GBA. Navigate through dangerous environments, solve light puzzles, and experience the epic struggle between Peter and Hook in this detailed adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peter-pan-the-movie-umode7', 'GAMEBOYADVANCE', 'Peter Pan The Movie (U)(Mode7)', '2002', 'Action', 'Griptonite Games', '1', 'Action Platformer', 'Action-adventure with exploration and cinematic storytelling.', 'Follow the movie''s plot to save Neverland from the pirates.', 'Movie-based action adventure featuring Peter Pan.', 'Peter Pan: The Motion Picture brings the live-action magic to GBA. Navigate through dangerous environments, solve light puzzles, and experience the epic struggle between Peter and Hook in this detailed adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---hamsterz-life-2-usir-vg', 'GAMEBOYADVANCE', 'Petz - Hamsterz Life 2 (U)(Sir VG)', '2006', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation focusing on breeding and caring for hamsters.', 'Raise happy hamsters and build the ultimate hamster park.', 'Adorable hamster care and breeding simulation.', 'Petz: Hamsterz Life 2 offers deep pet management. Feed, play with, and breed various hamster types while customizing their habitats. A perfect title for fans of cute animals and life simulation games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz-vet-urising-sun', 'GAMEBOYADVANCE', 'Petz Vet (U)(Rising Sun)', '2006', 'Simulation', 'Torus Games', '1', 'Veterinary Simulation', 'Veterinary simulation where you diagnose and treat domestic animals.', 'Heal sick pets and run a successful veterinary clinic.', 'Engaging pet doctor and clinic management sim.', 'Petz Vet turns your GBA into a medical center. Perform examinations, diagnose illnesses, and provide care for dogs, cats, and rabbits in this educational and heartwarming pet simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pferd-&-pony---mein-pferdehof-erising-sun', 'GAMEBOYADVANCE', 'Pferd & Pony - Mein Pferdehof (E)(Rising Sun)', '2005', 'Simulation', 'Tivola', '1', 'Horse Simulation', 'Horse breeding and stable management simulation.', 'Manage a farm, train horses, and win riding competitions.', 'Comprehensive horse farm management simulation.', 'Pferd & Pony: Mein Pferdehof (My Horse Farm) allows you to live the life of an equestrian professional. Balance the business of the farm with the care and training of your prize-winning horses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phalanx---the-enforce-fighter-a-144-eeurasia', 'GAMEBOYADVANCE', 'Phalanx - The Enforce Fighter A-144 (E)(Eurasia)', '2001', 'Shooter', 'Kemco', '1', 'Vertical Shooter', 'Side-scrolling shoot ''em up with multiple weapon systems.', 'Navigate the A-144 fighter through enemy lines and destroy bosses.', 'Intense sci-fi space shooter with high difficulty.', 'Phalanx is a classic SHMUP refined for the GBA. Choose your weapon loadout strategically, memorize enemy patterns, and survive the bullet hell in this port of the legendary space combat title.');
