INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-collection-epatience', 'GAMEBOYADVANCE', 'Phantasy Star Collection (E)(Patience)', '2002', 'RPG', 'Sega', '1', 'Japanese RPG Compilation', 'Turn-based JRPG collection featuring the first three Phantasy Star games.', 'Explore star systems and stop an ancient evil across generations.', 'Three legendary sci-fi RPG classics in one.', 'Phantasy Star Collection brings the foundations of the RPG genre to GBA. Experience epic storytelling, deep dungeon crawling, and strategic combat in this essential retro sci-fi compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-collection-umode7', 'GAMEBOYADVANCE', 'Phantasy Star Collection (U)(Mode7)', '2002', 'RPG', 'Sega', '1', 'Japanese RPG Compilation', 'Turn-based JRPG collection featuring the first three Phantasy Star games.', 'Explore star systems and stop an ancient evil across generations.', 'Three legendary sci-fi RPG classics in one.', 'Phantasy Star Collection brings the foundations of the RPG genre to GBA. Experience epic storytelling, deep dungeon crawling, and strategic combat in this essential retro sci-fi compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phil-of-the-future-urising-sun', 'GAMEBOYADVANCE', 'Phil of the Future (U)(Rising Sun)', '2004', 'Platform', 'Humongous Entertainment', '1', 'TV Show Platformer', 'Action-adventure with time-traveling gadgets and mini-games.', 'Fix the time machine and solve high school challenges.', 'Time-traveling adventure based on the Disney show.', 'Phil of the Future on GBA features gadgets from the future. Solve puzzles and complete missions to help Phil and his family survive the present while repairing their way back home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pia-carrot-e-youkoso!!-33-jrising-sun', 'GAMEBOYADVANCE', 'Pia Carrot e Youkoso!! 3.3 (J)(Rising Sun)', '2003', 'Visual Novel', 'NEC Interchannel', '1', 'Visual Novel', 'Visual novel and dating simulation set in a themed restaurant.', 'Build relationships with the staff while managing restaurant duties.', 'Japanese visual novel and romantic sim sequel.', 'Welcome to Pia Carrot 3.3, a polished Japanese adventure game. Balance your work life with social interactions in this beautifully illustrated entry of the famous romantic simulation series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pikapika-nurse-monogatari-jrising-sun', 'GAMEBOYADVANCE', 'Pikapika Nurse Monogatari (J)(Rising Sun)', '2004', 'Simulation', 'Angel', '1', 'Nursing Simulation', 'Life simulation and career-focused adventure in the nursing field.', 'Complete medical tasks and care for patients to become a top nurse.', 'Charming Japanese nurse career simulation.', 'Pikapika Nurse Monogatari lets you experience the daily life of a nurse. Engage in various medical mini-games and follow a heartwarming story in this unique Japanese GBA simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-advance-emenace', 'GAMEBOYADVANCE', 'Pinball Advance (E)(Menace)', '2002', 'Pinball', 'Digital Illusions', '1', 'Pinball', 'Realistic pinball physics with multiple themed tables.', 'Master the flippers and score points on various arcade tables.', 'Pure arcade-style pinball simulation for GBA.', 'Pinball Advance focuses on the core mechanics of the game. Featuring multiple table designs with unique challenges, it’s a solid choice for fans of classic silver-ball arcade action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-challenge-deluxe-emode7', 'GAMEBOYADVANCE', 'Pinball Challenge Deluxe (E)(Mode7)', '2002', 'Pinball', 'Paragon 5', '1', 'Pinball', 'Enhanced pinball compilation featuring multiple unique table designs.', 'Beat high scores and unlock table-specific secret features.', 'Diverse and challenging pinball table collection.', 'Pinball Challenge Deluxe offers a variety of themes and ball physics. Navigate ramps, hit bumpers, and trigger special events in this polished and addictive handheld pinball experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-tycoon-eindependent', 'GAMEBOYADVANCE', 'Pinball Tycoon (E)(Independent)', '2003', 'Simulation', 'Warthog Games', '1', 'Business Simulation', 'Business-themed pinball where scoring points builds an empire.', 'Manage resources and score points to grow your tycoon status.', 'Unique hybrid of pinball and management simulation.', 'Pinball Tycoon blends arcade action with strategic goals. Each table represents a business opportunity, making your high scores feel like real progress in this creative GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-tycoon-uvenom', 'GAMEBOYADVANCE', 'Pinball Tycoon (U)(Venom)', '2003', 'Simulation', 'Warthog Games', '1', 'Business Simulation', 'Business-themed pinball where scoring points builds an empire.', 'Manage resources and score points to grow your tycoon status.', 'Unique hybrid of pinball and management simulation.', 'Pinball Tycoon blends arcade action with strategic goals. Each table represents a business opportunity, making your high scores feel like real progress in this creative GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pink-panther-pinkadelic-pursuit-umugs', 'GAMEBOYADVANCE', 'Pink Panther Pinkadelic Pursuit (U)(Mugs)', '2002', 'Platform', 'Warthog Games', '1', 'Action Platformer', 'Side-scrolling action platformer with stealth and gadgets.', 'Find the treasure and outsmart enemies in a cartoon world.', 'Stylish platformer starring the Pink Panther.', 'Pink Panther: Pinkadelic Pursuit brings the iconic character''s flair to GBA. Use disguises and quick reflexes to navigate levels and avoid detection in this charming and funny adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinky-and-the-brain---the-master-plan-epatience', 'GAMEBOYADVANCE', 'Pinky And The Brain - The Master Plan (E)(Patience)', '2001', 'Puzzle', 'Kemco', '1', 'Puzzle Action', 'Isometric action-puzzle game with strategic character control.', 'Execute complex plans to take over the world.', 'Clever puzzle-adventure with the lab mice.', 'Pinky and the Brain: The Master Plan challenges your wit. Control both mice to solve puzzles and use gadgets in their latest attempt at global domination in this fun GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinky-monkey-town-jindependent', 'GAMEBOYADVANCE', 'Pinky Monkey Town (J)(Independent)', '2003', 'Simulation', 'Success', '1', 'Life Simulation', 'Colorful platforming and mini-game collection for younger players.', 'Explore the monkey town and interact with diverse characters.', 'Friendly and vibrant Japanese monkey adventure.', 'Pinky Monkey Town is a cheerful GBA game featuring a wide variety of activities. From simple platforming to fun mini-games, it’s a delightful experience for younger fans of the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinobee---wings-of-adventure-ueurasia', 'GAMEBOYADVANCE', 'Pinobee - Wings of Adventure (U)(Eurasia)', '2001', 'Platform', 'Artoon', '1', 'Action Platformer', 'Side-scrolling platformer with an emphasis on aerial movement.', 'Guide the robotic bee Pinobee through levels to find his creator.', 'High-speed aerial platforming with a robotic hero.', 'Pinobee: Wings of Adventure features a unique dashing mechanic that allows for fluid flight. Explore vibrant worlds and master the art of the dash in this creative GBA launch title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinobee-&-phoebee-jindependent', 'GAMEBOYADVANCE', 'Pinobee & Phoebee (J)(Independent)', '2001', 'Platform', 'Artoon', '1', 'Action Platformer', 'Expanded platforming adventure with cooperative mechanics.', 'Use both Pinobee and Phoebee to overcome new challenges.', 'Aerial platforming sequel with dual-hero action.', 'Pinobee & Phoebee takes the flight mechanics of the first game and adds more variety. Switch between characters or use their unique skills to navigate even more complex levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinobee-no-daibouken-jcapital', 'GAMEBOYADVANCE', 'Pinobee no Daibouken (J)(Capital)', '2001', 'Platform', 'Artoon', '1', 'Action Platformer', 'Side-scrolling platformer with an emphasis on aerial movement.', 'Guide the robotic bee Pinobee through levels to find his creator.', 'High-speed aerial platforming with a robotic hero.', 'Pinobee no Daibouken is the Japanese version of the acclaimed aerial platformer. Experience the original vision of Pinobee''s journey with its vibrant art and fluid flight mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pippa-funell-2-esir-vg', 'GAMEBOYADVANCE', 'Pippa Funell 2 (E)(Sir VG)', '2006', 'Simulation', 'Tivola', '1', 'Horse Simulation', 'Equestrian simulation with horse care and competitive riding.', 'Train your horse to compete in world-class equestrian events.', 'Professional horse riding and training simulation.', 'Pippa Funnell 2 (also known as Horsez) provides a detailed look at the world of professional riding. Focus on the bond with your horse while aiming for the championship trophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pippa-funnell---stable-adventures-esir-vg', 'GAMEBOYADVANCE', 'Pippa Funnell - Stable Adventures (E)(Sir VG)', '2006', 'Simulation', 'Tivola', '1', 'Horse Simulation', 'Equestrian simulation with horse care and competitive riding.', 'Train your horse to compete in world-class equestrian events.', 'Professional horse riding and training simulation.', 'Pippa Funnell: Stable Adventures focuses on the daily management of a stable. Care for multiple horses, manage your time, and prepare for top-tier competitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-the-caribbean---dead-mans-chest-urising-sun', 'GAMEBOYADVANCE', 'Pirates of the Caribbean - Dead Man''s Chest (U)(Rising Sun)', '2006', 'Action', 'Amaze Entertainment', '1', 'Action Adventure', 'Side-scrolling action combat and platforming based on the film.', 'Navigate the Caribbean and defeat Davy Jones'' crew.', 'Action-packed pirate adventure for the GBA.', 'Pirates of the Caribbean: Dead Man''s Chest delivers sword-fighting thrills. Play through key moments from the movie, upgrade your skills, and master the art of the pirate duel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-the-caribbean-etrsi', 'GAMEBOYADVANCE', 'Pirates of the Caribbean (E)(TRSI)', '2003', 'Action', 'Pocket Studios', '1', 'Action Adventure', 'Isometric action-adventure with exploration and naval combat.', 'Sail the seas, trade goods, and defeat enemy pirates.', 'Open-sea pirate life and combat simulation.', 'Pirates of the Caribbean on GBA offers a unique mix of land exploration and ship-to-ship combat. Build your reputation as a feared pirate and uncover the secrets of the sea.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-the-caribbean-uvenom', 'GAMEBOYADVANCE', 'Pirates of the Caribbean (U)(Venom)', '2003', 'Action', 'Pocket Studios', '1', 'Action Adventure', 'Isometric action-adventure with exploration and naval combat.', 'Sail the seas, trade goods, and defeat enemy pirates.', 'Open-sea pirate life and combat simulation.', 'Pirates of the Caribbean on GBA offers a unique mix of land exploration and ship-to-ship combat. Build your reputation as a feared pirate and uncover the secrets of the sea.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pitfall---the-lost-expedition-emenace', 'GAMEBOYADVANCE', 'Pitfall - The Lost Expedition (E)(Menace)', '2004', 'Action', 'Edge of Reality', '1', 'Action Adventure', '2D platformer with exploration, combat, and humor.', 'Explore the jungle to find your missing uncle and treasures.', 'Reimagined classic jungle adventure for GBA.', 'Pitfall: The Lost Expedition brings Harry back to the jungle. Use various tools, swing on vines, and battle dangerous creatures in this expansive and colorful platforming reboot.');
