INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pitfall---the-mayan-adventure-umode7', 'GAMEBOYADVANCE', 'Pitfall - The Mayan Adventure (U)(Mode7)', '2001', 'Platform', 'Activision', '1', 'Platformer', '2D side-scrolling platformer based on the 16-bit classic.', 'Navigate the Mayan ruins and defeat the evil spirit Zakelua.', 'Retro-style jungle platforming at its best.', 'Pitfall: The Mayan Adventure is a faithful port of the hit 16-bit title. Experience challenging jumps, secret paths, and classic action in this definitive portable version of Harry Jr.''s quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pixeline-i-pixieland-dindependent', 'GAMEBOYADVANCE', 'Pixeline I Pixieland (D)(Independent)', '2003', 'Educational', 'Independent', '1', 'Educational Adventure', 'Educational mini-games and platforming for children.', 'Complete puzzles and learn through diverse Pixieland activities.', 'Charming Danish educational game for kids.', 'Pixeline I Pixieland brings the popular Danish franchise to GBA. It features a variety of educational challenges designed to develop logic and memory skills while exploring a magical world filled with colorful characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('planet-monsters-erocket', 'GAMEBOYADVANCE', 'Planet Monsters (E)(Rocket)', '2001', 'Strategy', 'Crawfish Interactive', '1', 'Real-Time Strategy', '1-on-1 puzzle-battle action using falling blocks and character skills.', 'Defeat monster opponents by clearing blocks faster than them.', 'Competitive monster-themed puzzle-action game.', 'Planet Monsters is a fast-paced puzzle game for GBA. Choose your monster, master the block-clearing mechanics, and climb the ranks of the intergalactic tournament in this colorful and addictive handheld title.');
