INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('planet-of-the-apes-evenom', 'GAMEBOYADVANCE', 'Planet of the Apes (E)(Venom)', '2001', 'Action', 'Torus Games', '1', 'Action Adventure', '2D side-scrolling platformer with shooting and exploration.', 'Survive the ape-controlled world and uncover human history.', 'Action-platformer based on the sci-fi franchise.', 'Planet of the Apes for GBA follows the journey of a stranded astronaut. Battle aggressive apes, explore ruins, and solve environmental puzzles in this atmospheric handheld take on the classic cinematic story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('planet-of-the-apes-unobody', 'GAMEBOYADVANCE', 'Planet of the Apes (U)(Nobody)', '2001', 'Action', 'Torus Games', '1', 'Action Adventure', '2D side-scrolling platformer with shooting and exploration.', 'Survive the ape-controlled world and uncover human history.', 'Action-platformer based on the sci-fi franchise.', 'Planet of the Apes for GBA follows the journey of a stranded astronaut. Battle aggressive apes, explore ruins, and solve environmental puzzles in this atmospheric handheld take on the classic cinematic story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('play-novel---silent-hill-jrapid-fire', 'GAMEBOYADVANCE', 'Play Novel - Silent Hill (J)(Rapid Fire)', '2001', 'Visual Novel', 'Konami', '1', 'Horror Visual Novel', 'Visual novel with multiple branching paths and puzzle elements.', 'Survive the town of Silent Hill and uncover various endings.', 'Chilling psychological horror visual novel.', 'Play Novel: Silent Hill reimagines the horror classic for GBA. Experience the terrifying story through text and images, making critical choices that lead to different outcomes in this unique Japan-exclusive adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('play-yan-micro-jindependent', 'GAMEBOYADVANCE', 'Play-Yan Micro (J)(Independent)', '2005', 'Utility', 'Nintendo', '1', 'Media Player', 'Multimedia interface for playing music and video files via SD card.', 'Manage and play digital media files on GBA hardware.', 'Portable media player application for GBA.', 'Play-Yan Micro transforms your GBA into a pocket media center. This specialized cartridge allows for high-quality audio and video playback, showcasing the incredible versatility of the Game Boy Advance hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('playan---portable-av-player-jindependent', 'GAMEBOYADVANCE', 'Playan - Portable AV Player (J)(Independent)', '2004', 'Utility', 'Nintendo', '1', 'Media Player', 'Multimedia interface for playing music and video files via SD card.', 'Manage and play digital media files on GBA hardware.', 'Portable media player application for GBA.', 'Playan Portable AV Player is the definitive Japanese media tool for GBA. Load your favorite songs and videos onto an SD card to enjoy multimedia entertainment anywhere with this sleek interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-dogs-utrashman', 'GAMEBOYADVANCE', 'Pocket Dogs (U)(Trashman)', '2004', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation focused on caring for and dressing up dogs.', 'Raise a happy dog and participate in diverse activities.', 'Adorable puppy raising and care simulation.', 'Pocket Dogs (known as Poke Inu in Japan) lets you choose your favorite breed and care for it daily. Feed, groom, and play with your digital pup in this charming and relaxing handheld pet simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-music-evenom', 'GAMEBOYADVANCE', 'Pocket Music (E)(Venom)', '2002', 'Utility', 'Virgin Interactive', '1', 'Music Utility', 'Music creation and sequencing tool using synthesized sounds.', 'Compose and arrange your own digital music tracks.', 'Powerful pocket-sized music production studio.', 'Pocket Music turns your GBA into a synthesizer. Use the built-in sequencer and samples to create complex tracks, save your compositions, and experiment with electronic music on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-professor---kwik-notes-vol-1-uindependent', 'GAMEBOYADVANCE', 'Pocket Professor - Kwik Notes Vol. 1 (U)(Independent)', '2003', 'Educational', 'Independent', '1', 'Educational Utility', 'Educational software focused on note-taking and organization.', 'Improve study habits and organize digital notes.', 'Practical digital assistant for students.', 'Pocket Professor: Kwik Notes Vol. 1 is a productivity tool for GBA. It provides a simple interface for recording information and organizing thoughts, acting as a digital companion for learning and daily tasks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocky-&-rocky-with-becky-uvenom', 'GAMEBOYADVANCE', 'Pocky & Rocky with Becky (U)(Venom)', '2002', 'Action', 'Natsume', '2', 'Run and Gun', 'Top-down "cute ''em up" shooter with spiritual powers.', 'Defeat the evil spirits and bosses across diverse stages.', 'Classic Japanese shrine maiden shooting action.', 'Pocky & Rocky with Becky brings the legendary series to GBA. Use talismans and magic to fight off waves of monsters in this colorful and challenging top-down shooter that fans of the series will love.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poke-inu---poket-dogs-jindependent', 'GAMEBOYADVANCE', 'Poke Inu - Poket Dogs (J)(Independent)', '2003', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation focused on caring for and dressing up dogs.', 'Raise a happy dog and participate in diverse activities.', 'Adorable puppy raising and care simulation.', 'Poke Inu: Pocket Dogs lets you choose your favorite breed and care for it daily. Feed, groom, and play with your digital pup in this charming and relaxing handheld pet simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---liquid-crystal-version', 'GAMEBOYADVANCE', 'Pokemon - Liquid Crystal Version', '2020', 'RPG', 'Hack Community', '1', 'Monster RPG Hack', 'Turn-based JRPG with updated graphics and Johto/Kanto regions.', 'Collect all Johto gym badges and defeat the Elite Four.', 'Massive fan-remake of Pokemon Crystal for GBA.', 'Pokemon Liquid Crystal is an expansive RomHack that recreates the Gen 2 experience in the Gen 3 engine. Featuring real-time weather, day/night cycles, and a polished Johto region, it’s the ultimate way to relive a classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---too-many-types', 'GAMEBOYADVANCE', 'Pokemon - Too Many Types', '2021', 'RPG', 'Hack Community', '1', 'Monster RPG Hack', 'Turn-based JRPG featuring a massive roster of all existing types.', 'Conquer the league using over 150 different elemental types.', 'Experimental Pokemon RomHack with unique typing.', 'Pokemon Too Many Types is a creative hack that adds dozens of new elemental types to the game. Strategic depth is pushed to the limit as you learn new weaknesses and strengths in this chaotic and fun adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-altered-v1111', 'GAMEBOYADVANCE', 'Pokemon AlteRed (v1.11.1)', '2019', 'RPG', 'Hack Community', '1', 'Monster RPG Hack', 'Turn-based JRPG with "AlteRed" forms of classic creatures.', 'Explore a modified region and collect altered Pokemon.', 'Unique RomHack featuring redesigned Pokemon forms.', 'Pokemon AlteRed v1.11.1 introduces players to a world where classic Pokemon have entirely new appearances and types. Discover "AlteRed" forms and master a fresh meta-game in this visually distinct fan adventure.');
