INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-amalga-magenta-121', 'GAMEBOYADVANCE', 'Pokemon Amalga Magenta 1.2.1', '2021', 'RPG', 'Hack Community', '1', 'Monster RPG Hack', 'Turn-based JRPG with fused Pokemon and unique color schemes.', 'Traverse a magenta-themed world with fused team members.', 'Creative RomHack featuring fusion and color variants.', 'Pokemon Amalga Magenta 1.2.1 is a visually striking hack that focuses on amalgamation. Discover new fused creatures and explore a world with a distinct aesthetic in this polished fan-made title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-blazing-emerald', 'GAMEBOYADVANCE', 'Pokemon Blazing Emerald', '2020', 'RPG', 'Hack Community', '1', 'Monster RPG Hack', 'Turn-based JRPG with "Emerald" style but modern mechanics.', 'Complete the Hoenn Pokedex with updated moves and sprites.', 'Modernized and enhanced Pokemon Emerald experience.', 'Pokemon Blazing Emerald is an "enhancement hack" that keeps the spirit of Hoenn alive while adding modern quality-of-life features, new regional forms, and challenging endgame content.');
