INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-clover-v13', 'GAMEBOYADVANCE', 'Pokemon Clover v1.3', '2020', 'RPG', 'Hack Community', '1', 'Monster RPG Hack', 'Turn-based JRPG with satirical humor and completely original creatures.', 'Conquer the Fochun region and outsmart the memes.', 'Hilarious and high-quality parody Pokemon hack.', 'Pokemon Clover v1.3 is an internet culture masterpiece. Featuring 386 completely original "fakemon," a custom soundtrack, and a genuinely challenging difficulty, it’s one of the most famous hacks ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-conversion-emerald-beta-v176', 'GAMEBOYADVANCE', 'Pokemon Conversion Emerald Beta v176', '2023', 'RPG', 'Hack Community', '1', 'Monster RPG Hack', 'Turn-based JRPG focused on "Conversion" and type-changing mechanics.', 'Experiment with Pokemon forms to win the modified league.', 'Creative type-shifting Pokemon Emerald RomHack.', 'Pokemon Conversion Emerald Beta v176 introduces a world where types and forms are fluid. Discover new ways to battle and explore a familiar region with completely new rules and mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-crown-beta-1-v9', 'GAMEBOYADVANCE', 'Pokemon Crown (Beta 1 v9)', '2021', 'RPG', 'Hack Community', '1', 'Monster RPG Hack', 'Turn-based JRPG with an open-world medieval fantasy setting.', 'Traverse the Galar-inspired kingdom and become the monarch.', 'Stunning medieval-themed Pokemon RPG adventure.', 'Pokemon Crown is a groundbreaking hack that changes the GBA engine to support an open-world medieval world. Battle in unique ways and experience a deep story in this high-fidelity fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-dark-worship', 'GAMEBOYADVANCE', 'Pokemon Dark Worship', '2022', 'RPG', 'Hack Community', '1', 'Dark Themed Monster RPG Hack', 'Turn-based JRPG with a custom region and high-quality graphics.', 'Stop a dark cult and become the champion of the region.', 'Feature-rich Pokemon RomHack with an original story.', 'Pokemon Dark Worship offers a unique experience with a new region, Mega Evolutions, and Z-Moves. Face off against a mysterious cult in this polished GBA fan game that features high-end custom sprites and a deep narrative.');
