INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-darkfire', 'GAMEBOYADVANCE', 'Pokemon Darkfire', '2021', 'RPG', 'Hack Community', '1', 'Monster RPG Hack', 'Turn-based JRPG set in a new tropical region with original music.', 'Explore the Tenore region and uncover its ancient secrets.', 'Fresh GBA adventure with a unique tropical setting.', 'Pokemon Darkfire is a high-quality RomHack featuring an entirely new region, custom music, and a compelling storyline. Navigate through a tropical landscape and experience a fresh take on the classic Pokemon formula.');
