INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-demon-island-13f2', 'GAMEBOYADVANCE', 'Pokemon Demon Island 1.3f.2', '2020', 'RPG', 'Hack Community', '1', 'Dark Fantasy Monster RPG Hack', 'Survival-style turn-based JRPG on a dangerous isolated island.', 'Survive the threats of Demon Island and find a way to escape.', 'Hardcore survival Pokemon experience on GBA.', 'Pokemon Demon Island 1.3f.2 is a unique hack that blends monster catching with survival elements. Navigate a hostile environment where resources are scarce and every battle could be your last.');
