INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-crest-v103', 'GAMEBOYADVANCE', 'Pokemon Emerald Crest v1.0.3', '2021', 'RPG', 'Hack Community', '1', 'Enhanced Classic Monster RPG Hack', 'Open-world turn-based JRPG with massive Pokemon variety.', 'Explore Hoenn with modern features and thousands of catches.', 'The ultimate feature-rich Pokemon Emerald expansion.', 'Pokemon Emerald Crest v1.0.3 brings a modern feel to Hoenn. With Mega Evolution, Z-Moves, and a massive selection of Pokemon from all generations, it''s a comprehensive upgrade for Emerald fans.');
