INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-enhanced-v9302', 'GAMEBOYADVANCE', 'Pokemon Emerald Enhanced v9.302', '2023', 'RPG', 'Hack Community', '1', 'Quality of Life Monster RPG Hack', 'Turn-based JRPG with extensive customization and non-linear play.', 'Complete the game your way with hundreds of togglable options.', 'The most customizable Pokemon Emerald experience.', 'Pokemon Emerald Enhanced v9.302 is built for player freedom. With a follower system, difficulty toggles, and a non-linear quest system, it lets you experience Hoenn exactly how you want to.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-essence', 'GAMEBOYADVANCE', 'Pokemon Emerald Essence', '2022', 'RPG', 'Hack Community', '1', 'Enhanced Monster RPG Hack', 'Turn-based JRPG focused on a pure and balanced Emerald experience.', 'Become the champion of a refined and polished Hoenn.', 'A balanced and essential version of Pokemon Emerald.', 'Pokemon Emerald Essence strips away the clutter to provide a smooth, balanced, and high-quality replay of the classic game. Perfect for those who want the original feel with modern improvements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-extreme-randomizer', 'GAMEBOYADVANCE', 'Pokemon Emerald Extreme Randomizer', '2021', 'RPG', 'Hack Community', '1', 'Randomizer Monster RPG Hack', 'Turn-based JRPG with randomized encounters, items, and abilities.', 'Survive a chaotic and unpredictable journey through Hoenn.', 'The ultimate unpredictable Pokemon Emerald randomizer.', 'Pokemon Emerald Extreme Randomizer turns the world upside down. Every encounter is a surprise, making each playthrough a unique and often hilarious challenge for seasoned players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-multiplayer-alpha-4-v2', 'GAMEBOYADVANCE', 'Pokemon Emerald Multiplayer (Alpha 4 V2)', '2023', 'RPG', 'Hack Community', '2', 'Multiplayer Monster RPG Hack', 'Turn-based JRPG with real-time multiplayer connectivity.', 'Adventure through Hoenn with your friends in real-time.', 'Groundbreaking multiplayer Pokemon experience for GBA.', 'Pokemon Emerald Multiplayer allows you to see and interact with friends in the game world. Battle, trade, and explore together in this ambitious Alpha version that changes how we play GBA Pokemon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-multiplayer-alpha-064', 'GAMEBOYADVANCE', 'Pokemon Emerald Multiplayer Alpha 0.6.4', '2023', 'RPG', 'Hack Community', '2', 'Multiplayer Monster RPG Hack', 'Turn-based JRPG with real-time multiplayer connectivity.', 'Adventure through Hoenn with your friends in real-time.', 'Groundbreaking multiplayer Pokemon experience for GBA.', 'Pokemon Emerald Multiplayer Alpha 0.6.4 is a refined version of the social project. Experience improved stability and new multiplayer features as you journey through Hoenn with a community.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-rebirth-reborn', 'GAMEBOYADVANCE', 'Pokemon Emerald Rebirth Reborn', '2022', 'RPG', 'Hack Community', '1', 'Story Rewrite Monster RPG Hack', 'Turn-based JRPG with a dark storyline and revived ancient powers.', 'Navigate a world in chaos and stop the rebirth of evil.', 'A dark and intense reimagining of Pokemon Emerald.', 'Pokemon Emerald Rebirth Reborn features a more mature story and challenging encounters. Discover the secrets of ancient powers in this atmospheric and high-difficulty fan modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-rogue-ex-120', 'GAMEBOYADVANCE', 'Pokemon Emerald Rogue EX 1.2.0', '2023', 'RPG', 'Hack Community', '1', 'Roguelike Monster RPG Hack', 'Roguelike turn-based RPG with procedural runs and permadeath.', 'Complete a run by defeating the champion in a randomized world.', 'Addictive roguelike Pokemon action on GBA.', 'Pokemon Emerald Rogue EX 1.2.0 transforms the game into a roguelike. Build a team from scratch in each run, navigate random routes, and test your skills in this endlessly replayable GBA masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-rogue-ex-130', 'GAMEBOYADVANCE', 'Pokemon Emerald Rogue EX 1.3.0', '2023', 'RPG', 'Hack Community', '1', 'Roguelike Monster RPG Hack', 'Roguelike turn-based RPG with procedural runs and permadeath.', 'Complete a run by defeating the champion in a randomized world.', 'Addictive roguelike Pokemon action on GBA.', 'Pokemon Emerald Rogue EX 1.3.0 expands the roguelike experience with more Pokemon, new items, and refined hub mechanics. Every run is a new adventure in this highly polished fan game.');
