INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-seaglass-30', 'GAMEBOYADVANCE', 'Pokemon Emerald Seaglass 3.0', '2023', 'RPG', 'Hack Community', '1', 'Art Style Overhaul Monster RPG Hack', 'Turn-based JRPG with a stunning "HD-2D" inspired visual style.', 'Explore a beautiful, glass-like version of the Hoenn region.', 'The most visually unique Pokemon Emerald RomHack.', 'Pokemon Emerald Seaglass 3.0 features a breathtaking art style inspired by sea glass and modern retro games. Experience Hoenn with incredible new tiles and a cozy atmosphere that feels like a brand new game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emerald-slide-v36', 'GAMEBOYADVANCE', 'Pokemon Emerald Slide v3.6', '2022', 'RPG', 'Hack Community', '1', 'Minigame Focused Monster RPG Hack', 'Puzzle-adventure where you navigate the world using slide mechanics.', 'Solve movement puzzles to reach the end of the Pokemon world.', 'A creative and challenging Pokemon-themed puzzle game.', 'Pokemon Emerald Slide v3.6 changes the fundamental way you move. Navigate the world using "sliding" mechanics reminiscent of ice puzzles, creating a fresh and brain-teasing GBA experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-emeralds-eight-v15', 'GAMEBOYADVANCE', 'Pokemon Emerald''s Eight v1.5', '2021', 'RPG', 'Hack Community', '1', 'Challenge Based Monster RPG Hack', 'Turn-based JRPG with a focus on Boss Battles and the "Eight" challenges.', 'Defeat the eight legendary masters to prove your worth.', 'A boss-rush style Pokemon challenge for GBA.', 'Pokemon Emerald''s Eight v1.5 focuses on the most intense parts of the game: the boss battles. Prepare your team for high-level tactical encounters in this streamlined and challenging fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-ephemerald-v10', 'GAMEBOYADVANCE', 'Pokemon Ephemerald v1.0', '2022', 'RPG', 'Hack Community', '1', 'Enhanced Emerald Monster RPG Hack', 'Turn-based JRPG with a focus on temporary "ephemeral" mechanics.', 'Conquer the Hoenn region with unique time-limited challenges.', 'A fresh and fleeting take on Pokemon Emerald.', 'Pokemon Ephemerald v1.0 introduces unique mechanics that change how you interact with your team. Experience a modified Hoenn with balanced difficulty and new seasonal events in this polished GBA RomHack.');
