INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-fused-dimensions-v16', 'GAMEBOYADVANCE', 'Pokemon Fused Dimensions v1.6', '2021', 'RPG', 'Hack Community', '1', 'Fusion Mechanics Monster RPG Hack', 'Turn-based JRPG featuring completely original fused Pokemon.', 'Discover and collect hundreds of unique fused creatures.', 'Creative Pokemon fusion adventure on GBA.', 'Pokemon Fused Dimensions v1.6 introduces a world where every Pokemon is a fusion of two classics. Explore a modified Kanto and build a team of never-before-seen genetic hybrids.');
