INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-genesis', 'GAMEBOYADVANCE', 'Pokemon Genesis', '2016', 'RPG', 'Hack Community', '1', 'Original Region Monster RPG Hack', 'Turn-based JRPG with a new region and a focus on story origins.', 'Uncover the genesis of the Pokemon world in a new land.', 'Story-driven Pokemon adventure with a new region.', 'Pokemon Genesis features a completely original region, new characters, and a deep narrative. It’s a classic-style GBA RPG that focuses on high-quality world-building and exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-glazed-90', 'GAMEBOYADVANCE', 'Pokemon Glazed 9.0', '2022', 'RPG', 'Hack Community', '1', 'Story Driven Monster RPG Hack', 'Turn-based JRPG featuring multiple regions and a massive storyline.', 'Explore Tunod, Johto, and Rankor to become the champion.', 'One of the most famous and largest Pokemon RomHacks.', 'Pokemon Glazed 9.0 is a legendary fan game. With three regions to explore, a huge roster of Pokemon, and custom music, it provides a console-quality experience on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-gs-chronicles-271', 'GAMEBOYADVANCE', 'Pokemon GS Chronicles 2.7.1', '2021', 'RPG', 'Hack Community', '1', 'Johto Remake Monster RPG Hack', 'Turn-based JRPG with a heavy focus on the Johto and Kanto stories.', 'Experience a cinematic and detailed retelling of the GS era.', 'The most visually impressive Johto remake for GBA.', 'Pokemon GS Chronicles 2.7.1 is a masterpiece of RomHacking. It features custom tiles, an updated Johto map, Mega Evolution, and a deep, immersive story that feels like an official remake.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-inclement-emerald-v113', 'GAMEBOYADVANCE', 'Pokemon Inclement Emerald v1.13', '2023', 'RPG', 'Hack Community', '1', 'Difficulty Enhanced Emerald Monster RPG Hack', 'Turn-based JRPG with high difficulty and modern competitive features.', 'Defeat the toughest gym leaders in a modern Hoenn.', 'A professional-grade difficulty hack for Emerald.', 'Pokemon Inclement Emerald v1.13 is perfect for veterans. Featuring a full Pokedex, modern abilities, and incredibly smart AI, it is widely considered one of the best difficulty hacks ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-inflamed-red-b071', 'GAMEBOYADVANCE', 'Pokemon Inflamed Red b0.7.1', '2021', 'RPG', 'Hack Community', '1', 'Difficulty Enhanced FireRed Monster RPG Hack', 'Turn-based JRPG with intense difficulty and modern Kanto features.', 'Become the champion of a punishing and modernized Kanto.', 'A high-challenge remake of FireRed.', 'Pokemon Inflamed Red b0.7.1 is designed for those who find the original games too easy. With built-in Nuzlocke modes and competitive AI, it’s a brutal but rewarding Kanto experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-inflamed-red-v105', 'GAMEBOYADVANCE', 'Pokemon Inflamed Red v1.0.5', '2022', 'RPG', 'Hack Community', '1', 'Difficulty Enhanced FireRed Monster RPG Hack', 'Turn-based JRPG with intense difficulty and modern Kanto features.', 'Become the champion of a punishing and modernized Kanto.', 'Full release of the intense Inflamed Red hack.', 'Pokemon Inflamed Red v1.0.5 is the complete version of the project, featuring stabilized mechanics, Mega Evolution, and a massive roster of Pokemon to help you survive the intense difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-intel-alpha-102', 'GAMEBOYADVANCE', 'Pokemon Intel Alpha 1.0.2', '2021', 'RPG', 'Hack Community', '1', 'Experimental Monster RPG Hack', 'Turn-based JRPG with a tech-focused storyline and new mechanics.', 'Navigate a world of high-tech corporate espionage and Pokemon.', 'Sci-fi themed Pokemon adventure (Alpha).', 'Pokemon Intel Alpha 1.0.2 offers a unique perspective on the Pokemon world. With a more modern/sci-fi tone and new mission-based gameplay, it’s a fresh departure from the traditional gym circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-legends-arceus-beta-52', 'GAMEBOYADVANCE', 'Pokemon Legends Arceus Beta 5.2', '2023', 'RPG', 'Hack Community', '1', 'Legends Inspired Monster RPG Hack', 'Turn-based JRPG recreating the Hisui experience in 2D GBA style.', 'Research the first Pokedex in the ancient Hisui region.', 'A stunning GBA demake of Legends Arceus.', 'Pokemon Legends Arceus Beta 5.2 brings the Hisui region to the GBA. Featuring crafting, open-world elements, and Hisuian forms, it’s an incredible technical achievement in RomHacking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mega-mirage-of-tales---a-new-age-dawns-version-21-u2', 'GAMEBOYADVANCE', 'Pokemon Mega Mirage Of Tales - A New Age Dawns Version 2.1 u2', '2022', 'RPG', 'Hack Community', '1', 'Story Driven Monster RPG Hack', 'Turn-based JRPG with a non-linear world and massive quest system.', 'Carve your own path through a world filled with secrets.', 'A massive and non-linear Pokemon RPG adventure.', 'Pokemon Mega Mirage of Tales v2.1 u2 is a deep, choice-driven RPG. With a custom region, branching quests, and hidden secrets, it offers a level of player freedom rarely seen in the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mirage-of-tales-alpha-v33', 'GAMEBOYADVANCE', 'Pokemon Mirage of Tales (Alpha v3.3)', '2020', 'RPG', 'Hack Community', '1', 'Story Driven Monster RPG Hack', 'Turn-based JRPG with a non-linear world and massive quest system.', 'Carve your own path through a world filled with secrets.', 'Early access to the Mirage of Tales world.', 'Pokemon Mirage of Tales (Alpha v3.3) allows players to explore the early development of this ambitious non-linear project, featuring unique regional forms and a focus on player choice and exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-my-ass', 'GAMEBOYADVANCE', 'Pokemon My Ass', '2019', 'RPG', 'Hack Community', '1', 'Parody Monster RPG Hack', 'Humorous turn-based JRPG with adult themes and parody.', 'Navigate a crude and funny version of the Kanto region.', 'Satirical and adult-oriented Pokemon parody.', 'Pokemon My Ass is a famous humor-based RomHack. It takes the classic FireRed engine and fills it with adult jokes, a crude storyline, and unexpected twists, offering a completely different (and non-serious) GBA experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---red-rescue-team-ex', 'GAMEBOYADVANCE', 'Pokemon Mystery Dungeon - Red Rescue Team EX', '2023', 'RPG', 'Hack Community', '1', 'Dungeon Crawler Monster RPG Hack', 'Roguelike dungeon crawler with expanded roster and mechanics.', 'Complete rescue missions and explore procedural dungeons.', 'Enhanced Red Rescue Team with modern features.', 'Pokemon Mystery Dungeon: Red Rescue Team EX takes the classic GBA gameplay and adds modern Pokemon, new moves, and quality-of-life improvements that breathe new life into the beloved dungeon-crawling spin-off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---red-rescue-team-kaizo', 'GAMEBOYADVANCE', 'Pokemon Mystery Dungeon - Red Rescue Team Kaizo', '2022', 'RPG', 'Hack Community', '1', 'Difficulty Enhanced Dungeon RPG Hack', 'Hardcore roguelike dungeon crawler with extreme difficulty.', 'Survive the most punishing dungeons ever designed for PMD.', 'High-difficulty "Kaizo" version of Red Rescue Team.', 'Pokemon Mystery Dungeon: Red Rescue Team Kaizo is designed for veterans. With brutal enemy AI and limited resources, this hack tests your strategic management to the limit in a randomized dungeon environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-odyssey-beta-v15', 'GAMEBOYADVANCE', 'Pokemon Odyssey Beta v1.5', '2021', 'RPG', 'Hack Community', '1', 'Story Driven Monster RPG Hack', 'Turn-based JRPG with an exploration focus and sea-faring theme.', 'Explore the vast ocean and uncover the secrets of the Odyssey.', 'Ancient Greece-inspired Pokemon adventure.', 'Pokemon Odyssey Beta v1.5 is a unique hack that draws inspiration from mythology. Featuring sea exploration and a distinct aesthetic, it offers a fresh atmosphere and new regional variants for the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-orange---pokemon-naranja', 'GAMEBOYADVANCE', 'Pokemon Orange - Pokemon Naranja', '2018', 'RPG', 'Hack Community', '1', 'Classic Region Monster RPG Hack', 'Turn-based JRPG set in the tropical Orange Archipelago.', 'Collect the four Orange League badges and defeat Drake.', 'Faithful GBA remake of the Orange Islands anime arc.', 'Pokemon Orange (Pokemon Naranja) brings the fan-favorite anime season to life. Explore tropical islands, encounter pink Pokemon, and experience a story that official games never fully covered.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-order-and-chaos', 'GAMEBOYADVANCE', 'Pokemon Order and Chaos', '2020', 'RPG', 'Hack Community', '1', 'Open Progression Monster RPG Hack', 'Turn-based JRPG with a dualistic story and original region.', 'Restore the balance between Order and Chaos in the world.', 'Story-heavy RomHack with moral choices.', 'Pokemon Order and Chaos features a deep narrative where your decisions matter. Explore a new region with custom sprites and a soundtrack that emphasizes the conflict between the two titular forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-pisces-v154', 'GAMEBOYADVANCE', 'Pokemon Pisces v1.5.4', '2022', 'RPG', 'Hack Community', '1', 'Original Story Monster RPG Hack', 'Turn-based JRPG featuring a new region and strategic gameplay.', 'Conquer the league in a world where balance is key.', 'Polished GBA adventure with custom mechanics.', 'Pokemon Pisces v1.5.4 offers a high-quality Pokemon experience with a focus on balanced encounters and a fresh Pokedex. It includes modern features like Mega Evolution and a compelling new storyline.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-platinum-red-&-blue-versions---alpha-13', 'GAMEBOYADVANCE', 'Pokemon Platinum Red & Blue Versions - Alpha 1.3', '2021', 'RPG', 'Hack Community', '1', 'Dual Version Monster RPG Hack', 'Turn-based JRPG recreating the Sinnoh experience on GBA hardware.', 'Stop Team Galactic and become the champion of Sinnoh.', 'Ambitious GBA demake of Pokemon Platinum.', 'Pokemon Platinum Red & Blue Versions Alpha 1.3 aims to bring the fourth generation to the GBA engine. Explore a recreated Sinnoh region with classic 2D graphics and updated Gen 4 mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-pulsar-version-phase-2', 'GAMEBOYADVANCE', 'Pokemon Pulsar Version Phase 2', '2022', 'RPG', 'Hack Community', '1', 'Original Region Monster RPG Hack', 'Turn-based JRPG with a sci-fi theme and cosmic mystery.', 'Investigate the Pulsar anomaly and save the galaxy.', 'Cosmic-themed Pokemon adventure with a new region.', 'Pokemon Pulsar Version Phase 2 takes the series to a more technological setting. Featuring new regional forms and a futuristic plot, it’s a creative departure from the traditional fantasy elements of the series.');
