INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-quetzal-english-alpha8v2', 'GAMEBOYADVANCE', 'Pokemon Quetzal English Alpha8v2', '2023', 'RPG', 'Hack Community', '2', 'Multiplayer Monster RPG Hack', 'Multiplayer-focused turn-based JRPG with real-time interaction.', 'Adventure through a modified Hoenn with friends.', 'English version of the social Quetzal hack.', 'Pokemon Quetzal English Alpha8v2 brings the full multiplayer experience to English speakers. Featuring a massive roster and the ability to play with friends, it''s a revolutionary GBA fan game.');
