INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-rowe-v1811', 'GAMEBOYADVANCE', 'Pokemon R.O.W.E. v1.8.1.1', '2023', 'RPG', 'Hack Community', '1', 'Open World Emerald Monster RPG Hack', 'Open-world turn-based JRPG with total player freedom.', 'Explore the world in any order and build your dream team.', 'Advanced open-world JRPG with huge variety.', 'Pokemon R.O.W.E. v1.8.1.1 expands the post-game content and refines the follower system. It’s a dense, feature-packed version of the most free-form Pokemon game on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-rowe-v1822', 'GAMEBOYADVANCE', 'Pokemon R.O.W.E. v1.8.2.2', '2024', 'RPG', 'Hack Community', '1', 'Open World Emerald Monster RPG Hack', 'Open-world turn-based JRPG with total player freedom.', 'Explore the world in any order and build your dream team.', 'Stable and feature-complete open-world hack.', 'Pokemon R.O.W.E. v1.8.2.2 offers critical bug fixes for the v1.8 series, ensuring that your journey through the non-linear Hoenn region is as smooth and crash-free as possible.');
