INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-rowe-v205', 'GAMEBOYADVANCE', 'Pokemon R.O.W.E. v2.0.5', '2024', 'RPG', 'Hack Community', '1', 'Open World Emerald Monster RPG Hack', 'Open-world turn-based JRPG with total player freedom.', 'Explore the world in any order and build your dream team.', 'The peak of the R.O.W.E. open-world project.', 'Pokemon R.O.W.E. v2.0.5 is a landmark update, featuring the most stable and content-rich version of the project. It’s the ultimate way to experience a truly open-world Pokemon game on the GBA.');
