INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-radical-red-v40', 'GAMEBOYADVANCE', 'Pokemon Radical Red v4.0', '2023', 'RPG', 'Hack Community', '1', 'Difficulty Enhanced Monster RPG Hack', 'Competitive turn-based JRPG with extreme difficulty and modern features.', 'Defeat the toughest AI and become the champion of Kanto.', 'Massive update with Gen 9 Pokemon and mechanics.', 'Pokemon Radical Red v4.0 is a game-changer, adding Paldean Pokemon and the latest battle mechanics to the GBA engine. It’s a modern masterpiece of strategic RomHacking.');
