INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-retrieved-firered-version-0951', 'GAMEBOYADVANCE', 'Pokemon Retrieved firered (version 0.951)', '2021', 'RPG', 'Hack Community', '1', 'Story Rewrite Monster RPG Hack', 'Turn-based JRPG focusing on the retrieval of lost FireRed elements.', 'Explore a nostalgic but updated version of Kanto.', 'A faithful and polished Kanto "restoration" hack.', 'Pokemon Retrieved FireRed (v0.951) aims to enhance the original experience without losing its soul. It includes restored content and subtle improvements for a more complete classic journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-scale-x-fang-demo-v101', 'GAMEBOYADVANCE', 'Pokemon Scale x Fang (Demo v1.0.1)', '2023', 'RPG', 'Hack Community', '1', 'Demo Monster RPG Hack', 'Turn-based JRPG with a completely original story and unique regions.', 'Follow the destiny of the Scale and Fang in a new world.', 'Original Pokemon adventure with high-quality assets.', 'Pokemon Scale x Fang Demo v1.0.1 showcases an ambitious new project. With custom music, unique tiles, and a fresh narrative, it promises a high-fidelity RPG experience on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-scarlet-&-violet-172', 'GAMEBOYADVANCE', 'Pokemon Scarlet & Violet 1.7.2', '2023', 'RPG', 'Hack Community', '1', 'Modern Generation Monster RPG Hack', 'Turn-based JRPG demaking the Gen 9 experience for GBA hardware.', 'Explore a 2D version of Paldea and collect new creatures.', 'GBA-style demake of Scarlet and Violet.', 'Pokemon Scarlet & Violet 1.7.2 brings the ninth generation to the Game Boy Advance. Experience the Paldean Pokedex and story with classic 2D sprites and traditional GBA mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-shiny-gold-sigma-14', 'GAMEBOYADVANCE', 'Pokemon Shiny Gold Sigma 1.4', '2021', 'RPG', 'Hack Community', '1', 'Expanded Johto Monster RPG Hack', 'Turn-based JRPG with updated graphics and a massive Pokedex.', 'Relive the Johto journey with modern GBA enhancements.', 'A massive and colorful remake of Pokemon Gold/Silver.', 'Pokemon Shiny Gold Sigma 1.4 is one of the most content-dense Johto hacks. Featuring over 800 Pokemon and multiple regions, it’s an epic journey through the classic Pokemon world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-sonicmon-advance', 'GAMEBOYADVANCE', 'Pokemon sonicmon Advance', '2019', 'RPG', 'Hack Community', '1', 'Crossover Monster RPG Hack', 'Turn-based JRPG crossover with Sonic the Hedgehog elements.', 'Conquer the league with Sonic-themed Pokemon and characters.', 'Fast-paced crossover adventure between Sonic and Pokemon.', 'Pokemon Sonicmon Advance is a creative mashup. Experience the Pokemon world with a Sonic twist, featuring custom sprites and a unique atmosphere for fans of both franchises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-sovereign-of-the-skies-212', 'GAMEBOYADVANCE', 'Pokemon Sovereign of the Skies 2.1.2', '2022', 'RPG', 'Hack Community', '1', 'High Difficulty Monster RPG Hack', 'Turn-based JRPG with a massive original story and cinematic visuals.', 'Navigate a world in the clouds and save the sky kingdom.', 'One of the most visually stunning Pokemon hacks ever.', 'Pokemon Sovereign of the Skies 2.1.2 is a technical marvel. With custom graphics that push the GBA to its limits and an epic storyline, it feels like a professional RPG from a major studio.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-stranded-v016', 'GAMEBOYADVANCE', 'Pokemon Stranded v0.1.6', '2022', 'RPG', 'Hack Community', '1', 'Survival Monster RPG Hack', 'Survival-based turn-based JRPG on a deserted tropical island.', 'Scavenge for resources and survive with your Pokemon team.', 'Unique survival-themed Pokemon experiment.', 'Pokemon Stranded v0.1.6 is an early look at a survival-focused hack. Manage your hunger and health while exploring a mysterious island in this innovative take on the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-stranded-v067', 'GAMEBOYADVANCE', 'Pokemon Stranded v0.6.7', '2023', 'RPG', 'Hack Community', '1', 'Survival Monster RPG Hack', 'Survival-based turn-based JRPG on a deserted tropical island.', 'Scavenge for resources and survive with your Pokemon team.', 'Deep and challenging Pokemon survival simulation.', 'Pokemon Stranded v0.6.7 expands the survival mechanics and the island''s map. It’s a more complete and challenging version of this creative "lost at sea" Pokemon adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-super-glazed-version', 'GAMEBOYADVANCE', 'Pokemon Super Glazed Version', '2021', 'RPG', 'Hack Community', '1', 'Expanded Adventure Monster RPG Hack', 'Turn-based JRPG with expanded regions and new Pokemon.', 'Explore three diverse regions and stop a world-threatening plot.', 'Enhanced version of the legendary Glazed RomHack.', 'Pokemon Super Glazed Version takes the classic fan-favorite and adds even more content. With updated movesets, new Pokemon from later generations, and a massive world to explore, it''s the definitive way to play this GBA masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-the-last-renoval-red-v12', 'GAMEBOYADVANCE', 'Pokemon The Last Renoval Red v1.2', '2020', 'RPG', 'Hack Community', '1', 'Story Rewrite Monster RPG Hack', 'Turn-based JRPG featuring modern mechanics in a Kanto setting.', 'Become the champion of a modernized and polished FireRed.', 'A high-quality "faithful" enhancement of Kanto.', 'Pokemon The Last Renoval Red v1.2 focuses on bringing modern quality-of-life features to the original FireRed experience. Enjoy a balanced difficulty, physical/special split, and updated sprites in this polished GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-theta-emerald-renev-v23', 'GAMEBOYADVANCE', 'Pokemon Theta Emerald Renev v2.3', '2019', 'RPG', 'Hack Community', '1', 'Enhanced Classic Monster RPG Hack', 'Turn-based JRPG with a massive roster of over 700 Pokemon.', 'Complete the National Pokedex and conquer the Hoenn league.', 'Content-rich expansion of Pokemon Emerald.', 'Pokemon Theta Emerald Renev v2.3 is a massive upgrade to the Hoenn region. It features Mega Evolution, Primal Reversion, and hundreds of Pokemon from generations 1 through 7, all packed into the classic Emerald engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-ultimate-fusion', 'GAMEBOYADVANCE', 'Pokemon Ultimate Fusion', '2022', 'RPG', 'Hack Community', '1', 'Fusion Based Monster RPG Hack', 'Turn-based JRPG featuring a world of genetic hybrids.', 'Collect and battle with unique fused Pokemon creations.', 'Creative Pokemon fusion adventure for GBA.', 'Pokemon Ultimate Fusion offers a fresh take on the series where every encounter is a surprise. Discover powerful and bizarre fusions with custom types and movesets in this highly creative and addictive RomHack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-unbound-v210', 'GAMEBOYADVANCE', 'Pokemon Unbound v2.1.0', '2022', 'RPG', 'Hack Community', '1', 'Open World Monster RPG Hack', 'Narrative-driven turn-based JRPG with custom engine features.', 'Uncover the mystery of the Borrius region and stop the Shadows.', 'Widely considered the best Pokemon RomHack ever.', 'Pokemon Unbound v2.1.0 is a technical marvel on the GBA. Featuring a custom engine, a massive original story, difficulty modes, and a beautiful world, it offers a professional-quality experience that rivals official games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-unbound-v2111', 'GAMEBOYADVANCE', 'Pokemon Unbound v2.1.1.1', '2023', 'RPG', 'Hack Community', '1', 'Open World Monster RPG Hack', 'Narrative-driven turn-based JRPG with custom engine features.', 'Uncover the mystery of the Borrius region and stop the Shadows.', 'The most polished and feature-complete Pokemon fan game.', 'Pokemon Unbound v2.1.1.1 is the most stable version of this epic project. It includes numerous bug fixes and refined mechanics, ensuring the best possible experience in the incredible Borrius region.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-voyager-031', 'GAMEBOYADVANCE', 'Pokemon Voyager 0.3.1', '2023', 'RPG', 'Hack Community', '1', 'Exploration Focused Monster RPG Hack', 'Turn-based JRPG with a customizable world and randomizer options.', 'Sail through the Keiri region and solve the mystery of your origins.', 'Feature-heavy adventure with unique world-building.', 'Pokemon Voyager 0.3.1 introduces players to a world of sailing and exploration. With a heavy focus on player choice and a unique randomizer engine built-in, it offers endless replayability on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-voyager-033', 'GAMEBOYADVANCE', 'Pokemon Voyager 0.3.3', '2023', 'RPG', 'Hack Community', '1', 'Exploration Focused Monster RPG Hack', 'Turn-based JRPG with a customizable world and randomizer options.', 'Sail through the Keiri region and solve the mystery of your origins.', 'Refined sailing adventure with expanded features.', 'Pokemon Voyager 0.3.3 adds more story content and stabilizes the unique randomizer mechanics. Explore new islands and build a team in this highly original and ambitious GBA fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-voyager-035', 'GAMEBOYADVANCE', 'Pokemon Voyager 0.3.5', '2024', 'RPG', 'Hack Community', '1', 'Exploration Focused Monster RPG Hack', 'Turn-based JRPG with a customizable world and randomizer options.', 'Sail through the Keiri region and solve the mystery of your origins.', 'Polished exploration-focused Pokemon experience.', 'Pokemon Voyager 0.3.5 brings significant QoL updates to the Keiri region journey. Experience smoother sailing and more diverse encounters in this constantly evolving and creative GBA RomHack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-voyager-036', 'GAMEBOYADVANCE', 'Pokemon Voyager 0.3.6', '2024', 'RPG', 'Hack Community', '1', 'Exploration Focused Monster RPG Hack', 'Turn-based JRPG with a customizable world and randomizer options.', 'Sail through the Keiri region and solve the mystery of your origins.', 'The latest stable version of the Voyager project.', 'Pokemon Voyager 0.3.6 is the most refined iteration of the sailing RPG. Featuring a polished UI and balanced encounters, it’s the best way to experience this unique maritime Pokemon adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-waterred', 'GAMEBOYADVANCE', 'Pokemon WaterRed', '2019', 'RPG', 'Hack Community', '1', 'Water Themed Monster RPG Hack', 'Turn-based JRPG with an aquatic-themed Kanto world.', 'Navigate a flooded Kanto region and become the champion.', 'A unique "Water-type" focused remake of FireRed.', 'Pokemon WaterRed reimagines Kanto as an archipelago. With a focus on water-based travel and a modified roster, it offers a refreshing and challenging aquatic twist on the classic journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-waterred-version', 'GAMEBOYADVANCE', 'Pokemon WaterRed Version', '2019', 'RPG', 'Hack Community', '1', 'Water Themed Monster RPG Hack', 'Turn-based JRPG with an aquatic-themed Kanto world.', 'Navigate a flooded Kanto region and become the champion.', 'A unique "Water-type" focused remake of FireRed.', 'Pokemon WaterRed Version is the complete vision of this submerged Kanto adventure. Face off against modified gym leaders and explore a world where surfing is essential for survival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-wob-version-v11', 'GAMEBOYADVANCE', 'Pokemon Wob Version v1.1', '2021', 'RPG', 'Hack Community', '1', 'Experimental Monster RPG Hack', 'Turn-based JRPG featuring Wobbuffet-themed challenges and humor.', 'Survive a bizarre world dedicated to the patient Pokemon.', 'Hilarious and challenging Wobbuffet-themed hack.', 'Pokemon Wob Version v1.1 is a creative parody that centers around Wobbuffet. Experience unique battle mechanics and a funny storyline in this surprisingly deep and strategic GBA modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-yuval-beta-101', 'GAMEBOYADVANCE', 'Pokemon Yuval Beta 1.0.1', '2022', 'RPG', 'Hack Community', '1', 'Original Story Monster RPG Hack', 'Turn-based JRPG with a new region and deep lore.', 'Explore the Yuval region and stop an ancient threat.', 'Story-driven Pokemon adventure with custom assets.', 'Pokemon Yuval Beta 1.0.1 introduces an original world with high-quality tiles and a fresh Pokedex. It’s a promising new adventure for fans of classic-style GBA RPGs with a focus on exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon:-a-new-dawn-alpha-v02', 'GAMEBOYADVANCE', 'Pokemon: A New Dawn Alpha v0.2', '2023', 'RPG', 'Hack Community', '1', 'Original Story Monster RPG Hack', 'Turn-based JRPG featuring open-world elements and new story arcs.', 'Carve your own path in a reimagined Pokemon world.', 'Ambitious new-gen Pokemon adventure (Alpha).', 'Pokemon: A New Dawn Alpha v0.2 is an early look at a massive project that aims to modernize the GBA experience with open-world exploration and a more mature narrative style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('polarium-advance-esupplex', 'GAMEBOYADVANCE', 'Polarium Advance (E)(sUppLeX)', '2004', 'Puzzle', 'Mitchell', '1', 'Tile Matching Puzzle Game', 'Tile-based puzzle game with gravity and sequence mechanics.', 'Clear the screen by flipping tiles and matching colors.', 'Addictive and minimalist handheld puzzle game.', 'Polarium Advance is a brilliant adaptation of the DS hit. Solve hundreds of brain-teasing puzzles by drawing lines to flip tiles in this elegant and challenging GBA logic game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('polarium-advance-urising-sun', 'GAMEBOYADVANCE', 'Polarium Advance (U)(Rising Sun)', '2004', 'Puzzle', 'Mitchell', '1', 'Tile Matching Puzzle Game', 'Tile-based puzzle game with gravity and sequence mechanics.', 'Clear the screen by flipping tiles and matching colors.', 'Addictive and minimalist handheld puzzle game.', 'Polarium Advance is a brilliant adaptation of the DS hit. Solve hundreds of brain-teasing puzzles by drawing lines to flip tiles in this elegant and challenging GBA logic game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('polly-pocket-super-splash-island-esupplex', 'GAMEBOYADVANCE', 'Polly Pocket Super Splash Island (E)(sUppLeX)', '2003', 'Action', 'ArtePiazza', '1', 'Platform Adventure Game', 'Mini-game collection and exploration with a water park theme.', 'Complete fun water-based activities and collect items.', 'Bright and colorful casual game for younger players.', 'Polly Pocket Super Splash Island brings the popular toy brand to GBA. Enjoy a variety of mini-games like racing and puzzle-solving in a vibrant water park setting.');
