INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('polly-pocket!-usir-vg', 'GAMEBOYADVANCE', 'Polly Pocket! (U)(Sir VG)', '2002', 'Action', 'ArtePiazza', '1', 'Platform Adventure Game', 'Casual adventure and lifestyle game featuring Polly and friends.', 'Explore Polly''s world and complete diverse social tasks.', 'Charming fashion and friendship adventure.', 'Polly Pocket! for GBA allows fans to interact with Polly in her daily life. Choose outfits, play games, and explore the town in this accessible and fun title for younger audiences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pong-asteroids-yars-revenge-utrashman', 'GAMEBOYADVANCE', 'Pong, Asteroids, Yar''s Revenge (U)(Trashman)', '2004', 'Arcade', 'Atari', '2', 'Classic Arcade Compilation', 'Compilation of three classic Atari arcade games.', 'Reach high scores in Pong, Asteroids, and Yar''s Revenge.', 'Essential retro arcade collection for GBA.', 'This Atari collection brings three of the most influential games in history to your pocket. Experience the foundations of gaming with arcade-perfect ports of Pong and the intense space combat of Asteroids.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pop-idol-eevlstar', 'GAMEBOYADVANCE', 'Pop Idol (E)(EvlStar)', '2003', 'Music', 'Codemasters', '1', 'Music Rhythm Game', 'Rhythmic music game and career simulation based on the TV show.', 'Perform songs and impress the judges to become a pop star.', 'Engaging music-rhythm and fame simulation.', 'Pop Idol on GBA lets you experience the journey from audition to superstardom. Master the rhythm-based gameplay and customize your character to win the hearts of the public.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popeye---rush-for-spinach-uendless-piracy', 'GAMEBOYADVANCE', 'Popeye - Rush for Spinach (U)(Endless Piracy)', '2005', 'Action', 'Magic Pockets', '1', 'Classic Cartoon Platformer', 'Top-down racing and action game featuring classic characters.', 'Win the race to Greendale while collecting power-ups.', 'Wacky and competitive cartoon racing action.', 'Popeye: Rush for Spinach is a high-energy racer where characters use diverse items to gain the lead. It’s a fun and competitive take on the Popeye universe for fans of arcade racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('postman-pat-and-the-greendale-rocket-esir-vg', 'GAMEBOYADVANCE', 'Postman Pat and the Greendale Rocket (E)(Sir VG)', '2004', 'Adventure', 'Alternative Software', '1', 'Children TV Adventure Game', 'Educational and casual adventure based on the children''s series.', 'Help Postman Pat deliver mail and solve town problems.', 'Gentle and educational adventure for kids.', 'Postman Pat and the Greendale Rocket is a perfect game for young learners. Follow Pat as he helps his neighbors and drives his train in this charming and accessible GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-1&2-jindependent', 'GAMEBOYADVANCE', 'Power Pro Kun Pocket 1&2 (J)(Independent)', '1999', 'Sports', 'Konami', '1', 'Baseball Simulation Game', 'Baseball simulation combined with RPG-style career modes.', 'Manage a baseball career and win the Japanese league.', 'Two classic Power Pro games in one cartridge.', 'Power Pro Kun Pocket 1&2 brings the beloved hybrid of sports and life simulation to GBA. Train your player, manage their social life, and lead your team to victory in this deep Japanese classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-3-jcapital', 'GAMEBOYADVANCE', 'Power Pro Kun Pocket 3 (J)(Capital)', '2000', 'Sports', 'Konami', '1', 'Baseball Simulation Game', 'Baseball simulation combined with RPG-style career modes.', 'Manage a baseball career and win the Japanese league.', 'Deeply strategic baseball and life sim hybrid.', 'Power Pro Kun Pocket 3 expands the RPG elements, allowing for more complex player development. Experience the unique charm of the series with its wacky storylines and tight sports mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-4-jcezar', 'GAMEBOYADVANCE', 'Power Pro Kun Pocket 4 (J)(Cezar)', '2001', 'Sports', 'Konami', '1', 'Baseball Simulation Game', 'Baseball simulation combined with RPG-style career modes.', 'Manage a baseball career and win the Japanese league.', 'Engaging sports simulation with story-driven depth.', 'Power Pro Kun Pocket 4 continues the tradition of blending high-stakes baseball with a compelling narrative. Build your athlete from the ground up and conquer the pro scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-5-jpolla', 'GAMEBOYADVANCE', 'Power Pro Kun Pocket 5 (J)(Polla)', '2002', 'Sports', 'Konami', '1', 'Baseball Simulation Game', 'Baseball simulation combined with RPG-style career modes.', 'Manage a baseball career and win the Japanese league.', 'Refined sports and life management for GBA.', 'Power Pro Kun Pocket 5 introduces more variety in its mini-games and social interactions, making the journey to becoming a baseball star more immersive than ever.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-6-jrising-sun', 'GAMEBOYADVANCE', 'Power Pro Kun Pocket 6 (J)(Rising Sun)', '2003', 'Sports', 'Konami', '1', 'Baseball Simulation Game', 'Baseball simulation combined with RPG-style career modes.', 'Manage a baseball career and win the Japanese league.', 'The pinnacle of handheld Japanese baseball RPGs.', 'Power Pro Kun Pocket 6 features the series'' signature art style and deep mechanics. Balance training and personal life to create the ultimate champion in this polished GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-7-jcaravan', 'GAMEBOYADVANCE', 'Power Pro Kun Pocket 7 (J)(Caravan)', '2004', 'Sports', 'Konami', '1', 'Baseball Simulation Game', 'Baseball simulation combined with RPG-style career modes.', 'Manage a baseball career and win the Japanese league.', 'Final evolution of the series on the GBA hardware.', 'Power Pro Kun Pocket 7 offers the most content-dense experience in the GBA era. With refined controls and expanded story paths, it’s a must-play for fans of strategic sports games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---la-force-du-temps-feternity', 'GAMEBOYADVANCE', 'Power Rangers - La Force Du Temps (F)(Eternity)', '2001', 'Action', 'Natsume', '1', 'TV Series Action Game', 'Side-scrolling action with beat ''em up elements and platforming.', 'Fight through time to stop Ransik and his mutant army.', 'Heroic time-traveling action with the Power Rangers.', 'Power Rangers: Force du Temps (Time Force) brings the hit TV show to GBA. Switch between Rangers, use unique weapons, and battle mutants across different eras in this fast-paced action adventure.');
