INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---spd-utrashman', 'GAMEBOYADVANCE', 'Power Rangers - SPD (U)(Trashman)', '2005', 'Action', 'THQ', '1', 'TV Series Action Game', 'Beat ''em up action with multiple playable Rangers and vehicles.', 'Protect the city from alien invaders as part of the B-Squad.', 'Sci-fi action and combat with the SPD Rangers.', 'Power Rangers: Space Patrol Delta (SPD) features high-energy combat and unique special abilities. Play as your favorite Ranger, use tactical gadgets, and take down space criminals in this exciting handheld brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---time-force-gcezar', 'GAMEBOYADVANCE', 'Power Rangers - Time Force (G)(Cezar)', '2001', 'Action', 'THQ', '1', 'TV Series Action Game', 'Side-scrolling action with beat ''em up elements and platforming.', 'Fight through time to stop Ransik and his mutant army.', 'Heroic time-traveling action with the Power Rangers.', 'Power Rangers: Time Force on GBA is a classic action game where timing is key. Utilize the Timeforce Rangers'' unique skills to overcome obstacles and save the future from the mutant threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---time-force-umode7', 'GAMEBOYADVANCE', 'Power Rangers - Time Force (U)(Mode7)', '2001', 'Action', 'THQ', '1', 'TV Series Action Game', 'Side-scrolling action with beat ''em up elements and platforming.', 'Fight through time to stop Ransik and his mutant army.', 'Heroic time-traveling action with the Power Rangers.', 'Power Rangers: Time Force on GBA is a classic action game where timing is key. Utilize the Timeforce Rangers'' unique skills to overcome obstacles and save the future from the mutant threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---wild-force-ueurasia', 'GAMEBOYADVANCE', 'Power Rangers - Wild Force (U)(Eurasia)', '2002', 'Action', 'THQ', '1', 'TV Series Action Game', 'Isometric beat ''em up with environmental hazards and Zord battles.', 'Defeat the Orgs and protect the Animarium from destruction.', 'Nature-themed action with the Wild Force Rangers.', 'Power Rangers: Wild Force brings the power of the Animal Zords to GBA. Fight through hordes of Orgs and use team-based attacks to clear stages in this action-packed handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers-dino-thunder-erisingcaravan', 'GAMEBOYADVANCE', 'Power Rangers Dino Thunder (E)(RisingCaravan)', '2004', 'Action', 'THQ', '1', 'TV Series Action Game', 'Side-scrolling action platformer with character swapping.', 'Stop Mesogog from returning the Earth to the prehistoric age.', 'Dino-powered action featuring the Power Rangers.', 'Power Rangers Dino Thunder lets you control the Red, Blue, and Yellow Rangers. Use their Dino-Gems power to navigate levels and engage in massive Megazord battles in this fan-favorite GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers-dino-thunder-uvenom', 'GAMEBOYADVANCE', 'Power Rangers Dino Thunder (U)(Venom)', '2004', 'Action', 'THQ', '1', 'TV Series Action Game', 'Side-scrolling action platformer with character swapping.', 'Stop Mesogog from returning the Earth to the prehistoric age.', 'Dino-powered action featuring the Power Rangers.', 'Power Rangers Dino Thunder lets you control the Red, Blue, and Yellow Rangers. Use their Dino-Gems power to navigate levels and engage in massive Megazord battles in this fan-favorite GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers-pack-grising-sun', 'GAMEBOYADVANCE', 'Power Rangers Pack (G)(Rising Sun)', '2003', 'Action', 'THQ', '1', 'Compilation Action Game', 'Compilation of classic Power Rangers action titles in one.', 'Master various Ranger missions across different series.', 'Multi-game pack featuring Power Rangers hits.', 'This Power Rangers Pack is a treasure trove for fans, combining multiple adventures on a single cartridge. Experience the best of Ranger combat and Megazord action on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prehistorik-man-evenom', 'GAMEBOYADVANCE', 'Prehistorik Man (E)(Venom)', '1995', 'Platform', 'Titus', '1', 'Prehistoric Platformer', '2D platformer with slapstick combat and exploration.', 'Guide a hungry caveman through prehistoric levels to find food.', 'Quirky and colorful prehistoric platforming.', 'Prehistorik Man is a charming remake of the classic arcade title. Use your club to defeat dinosaurs, collect food items, and navigate tricky jumps in this humor-filled GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('premier-action-soccer-erising-sun', 'GAMEBOYADVANCE', 'Premier Action Soccer (E)(Rising Sun)', '2003', 'Sports', 'Raylight Studios', '4', 'Soccer Arcade Game', 'Arcade-style soccer with fast-paced matches and special moves.', 'Win the tournament by outscoring international rivals.', 'Fun and accessible handheld soccer action.', 'Premier Action Soccer focuses on the excitement of the pitch. Featuring simple controls and quick matches, it''s a perfect pick-up-and-play sports game for soccer fans on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('premier-manager-2003-04-ezbb', 'GAMEBOYADVANCE', 'Premier Manager 2003-04 (E)(ZBB)', '2003', 'Strategy', 'Zoo Digital', '1', 'Football Management Simulation', 'Football management simulation with deep tactical options.', 'Lead your chosen football club to the top of the league.', 'Strategic football team management and simulation.', 'Premier Manager 2003-04 allows you to control every aspect of a football club. Manage transfers, set tactics, and oversee finances to guide your team to glory in this detailed GBA sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('premier-manager-2004-05-erising-sun', 'GAMEBOYADVANCE', 'Premier Manager 2004-05 (E)(Rising Sun)', '2004', 'Strategy', 'Zoo Digital', '1', 'Football Management Simulation', 'Football management simulation with deep tactical options.', 'Lead your chosen football club to the top of the league.', 'Strategic football team management and simulation.', 'Premier Manager 2004-05 updates the database and refines the interface. Test your managerial skills as you handle the pressure of the professional football world on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('premier-manager-2005---2006-etrashman', 'GAMEBOYADVANCE', 'Premier Manager 2005 - 2006 (E)(Trashman)', '2005', 'Strategy', 'Zoo Digital', '1', 'Football Management Simulation', 'Football management simulation with deep tactical options.', 'Lead your chosen football club to the top of the league.', 'Strategic football team management and simulation.', 'Premier Manager 2005 - 2006 offers the most refined management experience in the series. Navigate complex seasons and prove you have what it takes to be the ultimate manager.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia---the-sands-of-time-erising-sun', 'GAMEBOYADVANCE', 'Prince of Persia - The Sands of Time (E)(Rising Sun)', '2003', 'Action', 'Ubisoft', '1', 'Cinematic Action Adventure', '2D side-scrolling platformer with parkour and time-rewind.', 'Navigate a trap-filled palace and defeat the Vizier.', 'Masterful cinematic platforming and action.', 'Prince of Persia: The Sands of Time on GBA captures the essence of the console version. Use acrobatic moves and the Dagger of Time to survive a perilous journey through ancient Persia.');
