INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-beach-soccer-epatience', 'GAMEBOYADVANCE', 'Pro Beach Soccer (E)(Patience)', '2003', 'Sports', 'Ocean Software', '4', 'Arcade Beach Soccer', 'Beach soccer simulation with acrobatic kicks and arcade feel.', 'Win matches on sandy courts around the world.', 'Stylish and fast-paced beach soccer simulation.', 'Pro Beach Soccer brings the sun and sand to your GBA. Execute overhead kicks and flashy tricks in this unique take on the sport, featuring real teams and vibrant environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-mahjong-tsuwamono-advance-jsupplex', 'GAMEBOYADVANCE', 'Pro Mahjong Tsuwamono Advance (J)(Supplex)', '2003', 'Board', 'Game Arts', '1', 'Mahjong Board Game', 'Digital version of the classic Japanese board game Mahjong.', 'Master Mahjong strategies and defeat skilled opponents.', 'Authentic and challenging Japanese Mahjong.', 'Pro Mahjong Tsuwamono Advance offers a detailed and traditional Mahjong experience. Practice your skills against intelligent AI in various tournament modes in this polished Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-tennis-wta-tour-epatience', 'GAMEBOYADVANCE', 'Pro Tennis WTA Tour (E)(Patience)', '2003', 'Sports', 'KCEO', '4', 'Professional Tennis Simulation', 'Realistic tennis simulation with WTA tour licensing.', 'Rise through the ranks of women''s professional tennis.', 'Official WTA tour licensed tennis simulation.', 'Pro Tennis WTA Tour features real players and venues. Master the court with diverse shots and strategic play to become the world''s number one female tennis player.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pukupuku-tennen-kairanban-jchakky', 'GAMEBOYADVANCE', 'PukuPuku Tennen Kairanban (J)(Chakky)', '2001', 'Puzzle', 'Taito', '1', 'Whimsical Puzzle Game', 'Adorable virtual pet and life simulation with various animals.', 'Care for cute creatures and interact with the town.', 'Charming Japanese pet care and life sim.', 'PukuPuku Tennen Kairanban is a heartwarming game about caring for small animals. Engage in mini-games and follow a sweet story in this visually delightful Japanese GBA experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pukupuku-tennen-kairanban-koi-no-cupid-daisakusen-jcaravan', 'GAMEBOYADVANCE', 'Pukupuku Tennen Kairanban Koi no Cupid Daisakusen (J)(Caravan)', '2002', 'Puzzle', 'Taito', '1', 'Whimsical Puzzle Game', 'Life simulation with a focus on matchmaking and romance.', 'Help the town''s characters find love through puzzles and tasks.', 'Heartwarming romance-themed life simulation.', 'Pukupuku Tennen Kairanban: Koi no Cupid Daisakusen tasks you with being a matchmaker. Use your social skills to bring characters together in this charming and colorful sequel.');
