INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('punch-king---arcade-boxing-umode7', 'GAMEBOYADVANCE', 'Punch King - Arcade Boxing (U)(Mode7)', '2000', 'Sports', 'Kidcorp', '2', 'Arcade Boxing Game', 'Arcade-style boxing with timing-based combat and special hits.', 'Climb the boxing ranks to become the world champion.', 'Fast and hard-hitting arcade boxing action.', 'Punch King: Arcade Boxing features a roster of colorful opponents. Master dodges, hooks, and super-punches to knock out the competition in this intense handheld brawler.');
