INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puppy-luv---spa-and-resort-usir-vg', 'GAMEBOYADVANCE', 'Puppy Luv - Spa and Resort (U)(Sir VG)', '2006', 'Simulation', 'Majesco', '1', 'Pet Care Simulation', 'Pet care and business management simulation for puppies.', 'Run a luxury spa for puppies and keep them happy.', 'Cute puppy spa management and care sim.', 'Puppy Luv: Spa and Resort lets you pamper a variety of adorable dogs. Wash, groom, and play with puppies to earn points and expand your pet resort in this relaxing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('purple-guy', 'GAMEBOYADVANCE', 'Purple Guy', '2023', 'Horror', 'Independent', '1', 'Indie Horror Game', 'Fan-made platformer or experimental horror adventure (contextual).', 'Navigate mysterious levels as the infamous Purple Guy.', 'Experimental adventure featuring the viral character.', 'Purple Guy for GBA is a unique fan-project or experimental title. Explore stylized levels and uncover hidden lore in this atmospheric and intriguing handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-pop-ebatman', 'GAMEBOYADVANCE', 'Puyo Pop (E)(BatMan)', '2002', 'Puzzle', 'Sonic Team', '2', 'Falling Block Puzzle', 'Falling-block puzzle with chain-reaction mechanics.', 'Match four or more Puyo of the same color to clear them and defeat opponents.', 'Iconic Japanese puzzle action with competitive multiplayer.', 'Puyo Pop (known as Puyo Puyo) brings its legendary chain-system to GBA. Outsmart your rivals by setting up massive combos and sending garbage blocks to their screen in this colorful and addictive puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-pop-umode7', 'GAMEBOYADVANCE', 'Puyo Pop (U)(Mode7)', '2002', 'Puzzle', 'Sonic Team', '2', 'Falling Block Puzzle', 'Falling-block puzzle with chain-reaction mechanics.', 'Match four or more Puyo of the same color to clear them and defeat opponents.', 'Iconic Japanese puzzle action with competitive multiplayer.', 'Puyo Pop (known as Puyo Puyo) brings its legendary chain-system to GBA. Outsmart your rivals by setting up massive combos and sending garbage blocks to their screen in this colorful and addictive puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-pop-fever-eendless-piracy', 'GAMEBOYADVANCE', 'Puyo Pop Fever (E)(Endless Piracy)', '2004', 'Puzzle', 'Sonic Team', '2', 'Falling Block Puzzle', 'Updated falling-block puzzle with the "Fever" gauge mechanic.', 'Build chains to enter Fever Mode and unleash massive damage on opponents.', 'Next-gen Puyo puzzle action with new characters.', 'Puyo Pop Fever refreshes the formula with a new cast and the Fever Mode mechanic. When your gauge fills, enter a rapid-fire chain state to turn the tide of battle in this vibrant handheld puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-fever-jcaravan', 'GAMEBOYADVANCE', 'Puyo Puyo Fever (J)(Caravan)', '2003', 'Puzzle', 'Sonic Team', '2', 'Falling Block Puzzle', 'Updated falling-block puzzle with the "Fever" gauge mechanic.', 'Build chains to enter Fever Mode and unleash massive damage on opponents.', 'Next-gen Puyo puzzle action with new characters.', 'Puyo Puyo Fever is the original Japanese version of the refreshed puzzle hit. Experience the refined Fever mechanics and charming art style that made this entry a fan favorite in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pyuu-to-fuku!-jogger-byuu-to-deru!-megane-kun-jeurasia', 'GAMEBOYADVANCE', 'Pyuu to Fuku! Jogger Byuu to Deru! Megane-Kun (J)(Eurasia)', '2004', 'Action', 'Toei Animation', '1', 'Comedy Action Game', 'Comedic mini-game collection based on the gag manga series.', 'Complete bizarre tasks and musical challenges to progress.', 'Wacky and surreal Japanese comedy adventure.', 'Pyuu to Fuku! Jogger (Jaguar) is a unique GBA experience based on the popular manga. Engage in absurd humor and diverse mini-games that capture the surreal spirit of the source material.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quad-desert-fury-uvenom', 'GAMEBOYADVANCE', 'Quad Desert Fury (U)(Venom)', '2003', 'Racing', 'Climax Racing', '1', 'ATV Racing Game', 'Off-road ATV racing with stunts and arcade physics.', 'Win intense desert races and upgrade your quad bike.', 'High-speed desert racing and ATV action.', 'Quad Desert Fury features dusty tracks and high-flying jumps. Master the handling of your ATV, outpace your competitors, and conquer the desert in this fast-paced GBA racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('qui-veut-gagner-des-millions-fpatience', 'GAMEBOYADVANCE', 'Qui Veut Gagner Des Millions (F)(Patience)', '2003', 'Trivia', 'Eidos', '4', 'Game Show Trivia', 'Trivia game based on the world-famous television show.', 'Answer 15 consecutive questions correctly to win the million.', 'French version of the legendary trivia quiz show.', 'Qui Veut Gagner Des Millions brings the tension of the TV studio to your GBA. Use your lifelines wisely and climb the money ladder in this challenging and educational trivia game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiere-ser-millionario-sindependent', 'GAMEBOYADVANCE', 'Quiere ser Millionario (S)(Independent)', '2003', 'Trivia', 'Eidos', '4', 'Game Show Trivia', 'Trivia game based on the world-famous television show.', 'Answer 15 consecutive questions correctly to win the million.', 'Spanish version of the legendary trivia quiz show.', '¿Quién Quiere Ser Millonario? lets you experience the ultimate quiz challenge in Spanish. Test your knowledge across various topics and see if you have what it takes to win the top prize.');
