INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('racing-fever-esupplex', 'GAMEBOYADVANCE', 'Racing Fever (E)(sUppLeX)', '2004', 'Racing', 'Magic Pockets', '4', 'Arcade Racing Game', 'Arcade-style top-down racing with various tracks and vehicles.', 'Outrun your rivals and finish first in high-speed street races.', 'Fast-paced top-down arcade racing action.', 'Racing Fever offers classic handheld racing thrills. Master the corners and use your speed to dominate a variety of urban and rural tracks in this accessible and fun GBA racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('racing-gears-advance-erising-sun', 'GAMEBOYADVANCE', 'Racing Gears Advance (E)(Rising Sun)', '2004', 'Racing', 'Vicarious Visions', '4', 'Arcade Racing Game', 'Isometric combat racing with licensed cars and weapon upgrades.', 'Win races while using gadgets and weapons to disable rivals.', 'Intense tactical racing and combat hybrid.', 'Racing Gears Advance is widely considered one of the best racers on GBA. Featuring 2D isometric graphics, licensed vehicles, and deep upgrade systems, it offers a perfect blend of speed and strategy.');
