INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampage---puzzle-attack-umode7', 'GAMEBOYADVANCE', 'Rampage - Puzzle Attack (U)(Mode7)', '2001', 'Puzzle', 'PopCap Games', '2', 'Action Puzzle Game', 'Tile-matching puzzle game featuring characters from the Rampage series.', 'Clear blocks to help the giant monsters destroy cities.', 'Destructive puzzle action with a monster twist.', 'Rampage: Puzzle Attack combines classic block-matching gameplay with the charm of the city-smashing franchise. Link colors and trigger combos to fuel the monsters'' path of destruction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rapala-pro-fishing-uvenom', 'GAMEBOYADVANCE', 'Rapala Pro Fishing (U)(Venom)', '2006', 'Sports', 'Magic Wand', '1', 'Fishing Simulation', 'Realistic fishing simulation with professional equipment and locations.', 'Catch specific fish species and win professional tournaments.', 'Detailed and immersive professional fishing sim.', 'Rapala Pro Fishing offers an authentic experience for angling enthusiasts. Choose the right lure, manage your line, and battle the biggest fish in legendary North American waters.');
