INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman---hoodlums-revenge-eendless-piracy', 'GAMEBOYADVANCE', 'Rayman - Hoodlums'' Revenge (E)(Endless Piracy)', '2005', 'Action', 'Ubisoft', '1', 'Action Adventure Platformer', 'Isometric action-adventure with combat and exploration.', 'Defeat the Hoodlums and save the Glade of Dreams.', 'Unique isometric adventure starring Rayman.', 'Rayman: Hoodlums'' Revenge offers a different perspective on the franchise. Control Rayman and Globox through clever levels filled with puzzles and enemies in this engaging handheld sequel.');
