INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman---raving-rabbids-erising-sun', 'GAMEBOYADVANCE', 'Rayman - Raving Rabbids (E)(Rising Sun)', '2006', 'Action', 'Ubisoft', '4', 'Party Action Game', '2D side-scrolling platformer with a focus on wacky enemies.', 'Navigate surreal worlds and outsmart the chaotic Rabbids.', 'Action-packed platformer featuring the crazy Rabbids.', 'Rayman: Raving Rabbids on GBA is a classic 2D platformer at heart. Avoid traps, punch enemies, and enjoy the humor of the Rabbids in this visually impressive and fun title.');
