INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman-10th-anniversary-utrashman', 'GAMEBOYADVANCE', 'Rayman 10th Anniversary (U)(Trashman)', '2005', 'Platform', 'Ubisoft', '1', 'Platformer Compilation', 'Compilation featuring Rayman Advance and Rayman 3 on one cartridge.', 'Experience the best of Rayman''s early adventures.', 'Two legendary Rayman platformers in one pack.', 'Rayman 10th Anniversary celebrates the limbless hero. Enjoy the challenging original Rayman and the refined action of Rayman 3 in this essential GBA collection for platforming fans.');
