INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman-3---hoodlum-havoc-eeurasia', 'GAMEBOYADVANCE', 'Rayman 3 - Hoodlum Havoc (E)(Eurasia)', '2003', 'Platform', 'Ubisoft', '1', '3D Action Platformer', '2D side-scrolling action platformer with multiple power-ups.', 'Stop the Hoodlums and save Rayman’s friend Globox.', 'Polished and vibrant handheld Rayman adventure.', 'Rayman 3: Hoodlum Havoc on GBA is an original 2D platformer. Featuring beautiful sprites, tight controls, and creative level design, it’s one of the best platforming experiences on the system.');
